insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('94f0d91e-dec0-5225-bc09-a809e2d1db5e', '2026-27', 'optional', 'ACT/SAT are not required for admission; they may be submitted for placement or as supplemental information. Admission criteria can be met by any one of: top 25% of class, 3.00 unweighted competency GPA, ACT 22 (24 nonresident) or SAT 1120 (1180 nonresident), plus course competencies. Some programs have higher thresholds.', '0a27f02f-e61c-526d-b0ff-c15c473c1403');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('94f0d91e-dec0-5225-bc09-a809e2d1db5e', '2026-27', array['common_app','own']::text[], 90, 'Application fee is $55 Arizona residents, $85 domestic nonresidents, $90 international nonresidents. Applicants can use the ASU application or the Common App. CDS C7 lists essay and recommendations as not considered; teacher/counselor rec counts and interview policy are not stated on the admissions pages.', '0a27f02f-e61c-526d-b0ff-c15c473c1403');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('b73d0f0a-8212-5b83-ac5b-12bed9b9013c', '94f0d91e-dec0-5225-bc09-a809e2d1db5e', '2026-27', 'priority', null, 'Priority admission date (fall 2027 entry)', '2026-11-01', 'ASU admits on a rolling basis; Nov. 1 is the published priority date. Nursing (BSN) direct admission also uses a Nov. 1 priority date.', '0a27f02f-e61c-526d-b0ff-c15c473c1403'),
 ('06bb3c9e-bdfa-54f9-99b8-cb9d4ce9818d', '94f0d91e-dec0-5225-bc09-a809e2d1db5e', '2026-27', 'application', 'ROLLING', 'Regular admission date (fall 2027 entry)', '2027-01-15', 'The /apply/first-year/admission page says Jan. 15; the /apply/first-year page says Feb. 1. Notification dates are not published (rolling).', '0a27f02f-e61c-526d-b0ff-c15c473c1403'),
 ('c6fa8e51-c1bd-5d46-8e1b-0f5ff85e23a6', '94f0d91e-dec0-5225-bc09-a809e2d1db5e', '2026-27', 'financial_aid', null, 'FAFSA priority filing date', '2027-01-15', 'Applies to U.S. citizens/eligible noncitizens; international students are not eligible for federal aid.', '57a6c397-d33b-5818-b218-444a36b2c13e');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('94f0d91e-dec0-5225-bc09-a809e2d1db5e', 'required_nonnative', 'Automatic exemption for U.S. citizens/permanent residents and citizens of listed English-speaking countries. Form-based exemptions: 48 transferable U.S. college credits (GPA 2.50+, incl. 6 credits first-year English); 2 years US high school (juniors+seniors) with ACT English 23+ or SAT EBRW 580+; 4 years US high school; or secondary diploma from an institution where English was the sole medium of instruction. Scores must be no more than 2 years old at start date.', 'a1e309d4-18ad-55ca-9ff5-1a4c9cc7e864');
insert into english_requirements (institution_id, source_id, test_key, status, min_total, min_subscores, notes)
select '94f0d91e-dec0-5225-bc09-a809e2d1db5e'::uuid, 'a1e309d4-18ad-55ca-9ff5-1a4c9cc7e864'::uuid, v.* from (values
 ('TOEFL_IBT', 'required_option', 61, null, 'General programs, exams taken before 2026-01-21. Higher for specific programs: Nursing BSN 76, Fulton Engineering 79, Cronkite Journalism 100. Paper edition not accepted; Home Edition accepted for exams on/after 2026-01-21.'),
 ('TOEFL_IBT_2026', 'required_option', 3.5, '{"each_section": 3.5}'::jsonb, 'Exams on/after 2026-01-21, general programs. Nursing BSN 4, Fulton Engineering 4, Cronkite 5. The page lists these values without naming the 1-6 scale.'),
 ('IELTS', 'required_option', 6.0, null, 'Academic, Online, UKVI, Indicator accepted; General Training not accepted. Nursing BSN 6.5, Fulton Engineering 6.5, Cronkite 7.0.'),
 ('DUOLINGO', 'required_option', 95, null, 'Nursing BSN 100, Fulton Engineering 105, Cronkite 120.'),
 ('PTE', 'required_option', 53, null, 'Fulton Engineering 58, Cronkite 73; not accepted for Nursing BSN; PTE Academic Online not accepted.'),
 ('CAMBRIDGE', 'accepted', 170, null, 'B2 First, C1 Advanced, C2 Proficiency. Nursing BSN 176, Fulton Engineering 176, Cronkite 185.')) v;
