insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, room_board_usd, books_usd, other_usd, total_coa_usd, intl_aid_policy, merit_scholarships, notes, source_id) values
 ('461ac61b-e5fb-59fc-bb4c-0f9ea5ca2be4', '2023-2024', 11036, 32466, 18064, 1500, 5322, 31688, 'merit_only', true, 'College Scorecard (IPEDS 2023-24): tuition includes required fees; on-campus cost of attendance.; UB offers scholarships in varying amounts to incoming first-year international students with no prior college credit (fall or spring entry), renewable up to four years; all admitted international students are automatically considered. The scholarships page does not mention need-based aid for international students, so that is left unconfirmed.', '9745a95e-e0b6-5a17-b225-f63bd1f7a235');
