insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, notes, source_id, source_note) values
 ('a3ca69f7-eabd-5caa-bc58-5d9f4678ad29', '2023-2024', 48591, 42149, 7070, 'Baseline from IPEDS (fall 2023 first-time, first-year class); College Navigator also shows fall 2024: 53,559 applicants, 91% admitted, 14% of admitted students enrolled (percentages are rounded). No public Common Data Set page was found on fullerton.edu. Undergraduate enrollment and international (nonresident) undergraduates are IPEDS fall 2023 totals. Applications by residency (international applicants and admits), GPA and score ranges are not in IPEDS, so they are left null. The CSU is test-blind, so no SAT/ACT percentiles are reported.', '376be4a9-5975-57f5-beac-d2dc5d2a0e59', 'admissions_site');
insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('a3ca69f7-eabd-5caa-bc58-5d9f4678ad29', '2026-27', 'blind', 'The CSU system no longer uses SAT/ACT in admission decisions; College Navigator (IPEDS fall 2024 admissions) lists SAT/ACT as ''Not considered (Test Blind)''. Admission uses a Multi Factor Admission Score for U.S. graduates and a ''competitive GPA'' for graduates of schools outside the U.S.', '932b8532-901f-5d86-8ea4-71a0e7520762');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('a3ca69f7-eabd-5caa-bc58-5d9f4678ad29', '2026-27', array['own']::text[], 70, 'Apply through Cal State Apply; $70 fee. Graduates of schools outside the U.S. need 3 years of mathematics (algebra, geometry, intermediate algebra) and a competitive GPA (no number published); full A-G courses are required only for U.S. high school graduates. Official transcripts with certified translations; passport copy and recent financial documents (under 6 months) are needed for the I-20. Some majors have supplemental requirements. College Navigator shows essays and recommendations are not considered.', '76291d3c-6fb8-5bcc-8cee-b8462de3133b');
insert into deadlines (id, institution_id, cycle, kind, label, due_date, notes, source_id) values
 ('4bbf2439-ed0a-53ce-aae1-520409b7468c', 'a3ca69f7-eabd-5caa-bc58-5d9f4678ad29', '2026-27', 'application', 'First-year application filing period closes, Cal State Apply (fall 2027)', '2026-11-30', 'Cal State Apply opens Aug 1, 2026 and submissions run Oct 1 to Nov 30, 2026. CSUF''s international pages say applications open Oct 1 for fall but publish no separate international deadline, so plan for Nov 30, 2026 unless the admissions office confirms a later date.', 'a4967210-0e26-5d76-ab52-b78f310fea36'),
 ('7b3c9b8c-a73e-5a3d-832e-a176a15ef3e0', 'a3ca69f7-eabd-5caa-bc58-5d9f4678ad29', '2026-27', 'other', 'Official initial transcripts due (selected students only)', '2027-02-15', null, 'a4967210-0e26-5d76-ab52-b78f310fea36'),
 ('86d91198-edc6-5287-a8fb-4378c3e8abbc', 'a3ca69f7-eabd-5caa-bc58-5d9f4678ad29', '2026-27', 'deposit', 'Intent to Enroll deadline', '2027-05-01', null, 'a4967210-0e26-5d76-ab52-b78f310fea36'),
 ('a116e685-7b84-58ef-b203-25bc6fc9547d', 'a3ca69f7-eabd-5caa-bc58-5d9f4678ad29', '2026-27', 'other', 'Final deadline for final official transcripts', '2027-07-15', 'Priority date for final transcripts is July 1, 2027.', 'a4967210-0e26-5d76-ab52-b78f310fea36');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('a3ca69f7-eabd-5caa-bc58-5d9f4678ad29', 'required_nonnative', 'The page says additional options to meet the requirement are available and some countries are exempt, but does not list them. It names no Duolingo, Cambridge or new-scale TOEFL minimum for first-time freshmen.', '76291d3c-6fb8-5bcc-8cee-b8462de3133b');
