insert into cost_aid (institution_id, year, tuition_usd, required_fees_usd, room_board_usd, books_usd, other_usd, intl_aid_policy, intl_need_aid, intl_need_aid_awarded, intl_avg_award_usd, meets_full_need, merit_scholarships, notes, source_id) values
 ('3ed3721b-9031-5fe0-89f6-7beea7e2f31f', '2026-2027', 68574, 3255, 21996, 1428, 3969, 'need_aware_full_need', true, 59, 85696, true, false, 'CDS G1 (first-year, 2026-2027): tuition $68,574, required fees $3,255, food and housing $21,996; G5 residents: books $1,428, other expenses $3,969. H6: need-based institutional aid for nonresidents, 59 awarded, average $85,696, total $5,056,044. SAT composite percentiles are blank in CDS C9 (only section scores reported).; Need-blind for U.S. citizens and permanent residents, need-aware for international applicants; meets 100% of demonstrated need for admitted students. International students must apply for aid at application time to be eligible later. Caltech does not award merit scholarships. Financial aid deadlines for the 2026-27 cycle were not yet posted (the aid pages still show fall 2026 entry).', '1817c517-de31-5c09-b4d4-fb698fb46e4e');
insert into institution_tiers (institution_id, category_key, tier_code, rationale)
select '3ed3721b-9031-5fe0-89f6-7beea7e2f31f'::uuid, v.* from (values
 ('general', 'S+', 'Admit rate 3.8%'),
 ('computer_science', 'A', 'Top-15 CS (CMS department), small and theory-heavy.'),
 ('engineering', 'A', 'Top-10 engineering; small, so fewer specializations than large engineering schools.'),
 ('business', 'C', 'No business school; the Business, Economics & Management (BEM) major is the closest option.'),
 ('biology_life_sci', 'S', 'Biology is a top-5 US department.'),
 ('pre_med', 'B', 'No medical school and a small pre-med population.'),
 ('economics', 'B', 'Small but research-strong economics (experimental and social sciences).'),
 ('math_physics', 'S', 'Physics and mathematics are among the very best in the US.'),
 ('humanities', 'C', 'History, English and philosophy majors exist but are not the focus.')) v;

