insert into application_requirements (institution_id, cycle, platforms, teacher_recs, counselor_rec, app_fee_usd, fee_waiver, notes, source_id) values
 ('7e265859-92d1-5be8-b5aa-69601baaa5de', '2026-27', array['common_app','coalition']::text[], 2, true, 75, true, 'Common App or Coalition with Scoir. Required: official high school transcript, School Report, counselor recommendation, two teacher recommendations, an essay (all first-year students) and the $75 fee (waivers available). Music and music-education applicants need an Arts Supplement. Pre-Professional Scholars applicants write two additional essays plus an interview in late March if selected as a finalist. Applicants seeking need-based aid must indicate it on the application and submit financial aid documents for the application to be complete: non-U.S. residents submit the CSS Profile only (CSS code 1105); U.S. citizens and permanent residents submit FAFSA plus CSS Profile. The page does not state a year, so dates are taken as the current cycle.', '110f7407-c72b-5c21-9536-718311cc6c48');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notification_date, notes, source_id) values
 ('7ef6bd70-6d7a-50ac-b404-deee45988ebd', '7e265859-92d1-5be8-b5aa-69601baaa5de', '2026-27', 'application', 'ED', 'Early Decision I (binding)', '2026-11-01', '2026-12-05', 'Anticipated notification Dec 5; deposit due Dec 12; financial aid documents due Nov 15.', '2f070da0-75af-560d-801a-1886a512f10b'),
 ('9351e0bf-029f-560d-be26-c6331c31665b', '7e265859-92d1-5be8-b5aa-69601baaa5de', '2026-27', 'application', 'EA', 'Early Action (non-binding)', '2026-11-01', '2026-12-19', 'Anticipated notification Dec 19; reply by May 1; financial aid documents due Nov 15.', '2f070da0-75af-560d-801a-1886a512f10b'),
 ('68a41462-eba8-5724-ad83-8c0b9fec608d', '7e265859-92d1-5be8-b5aa-69601baaa5de', '2026-27', 'application', 'ED2', 'Early Decision II (binding)', '2027-01-15', '2027-02-06', 'Anticipated notification Feb 6; deposit due 1 week after admission; financial aid documents due Jan 22.', '2f070da0-75af-560d-801a-1886a512f10b'),
 ('27809b6b-72b9-5bdd-b9f2-86a8cb942be0', '7e265859-92d1-5be8-b5aa-69601baaa5de', '2026-27', 'application', 'RD', 'Regular Decision', '2027-01-15', '2027-03-20', 'Anticipated notification Mar 20; reply by May 1; financial aid documents due Feb 1. The separate Pre-Professional Scholars Program (conditional medical/dental admission) closes Dec 1 with notification Jan 30.', '2f070da0-75af-560d-801a-1886a512f10b');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
