insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('d8057782-44e3-5e2c-998a-2f53fcba2556', '2026-27', 'optional', 'International first-year applicants qualify with a high school GPA of 2.70 or equivalent (SAT/ACT not required), or with SAT 1030+ (reading + math) or ACT 20+. Students admitted on grades without scores take UCO''s Computerized Placement Test before enrolling.', 'f7c98104-162e-57b1-a940-a53f8daa3085');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('d8057782-44e3-5e2c-998a-2f53fcba2556', '2026-27', array['own']::text[], 40, 'Online application on UCO''s own portal; $40 non-refundable fee. Documents: transcripts (equivalent of 12 years of schooling, with certified English translation if needed), English proficiency, passport, and for F-1 a bank statement (minimum $29,950 for a degree-seeking undergraduate) plus a Statement of Financial Sponsorship. UCO School of Music applicants also submit an audition form.', 'a2cac4a8-c2a9-5d42-99bb-ad6897899cfc');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('4b03775e-f12a-5ece-9750-eeed9983a20c', 'd8057782-44e3-5e2c-998a-2f53fcba2556', '2026-27', 'application', 'ROLLING', 'Application (fall 2027): no published deadline', null, 'UCO states there are no specific application deadlines for undergraduate international applicants and recommends applying as early as possible for processing, visa and travel.', 'f7c98104-162e-57b1-a940-a53f8daa3085'),
 ('69ea92b9-9dd4-5ac7-be78-14596186d483', 'd8057782-44e3-5e2c-998a-2f53fcba2556', '2026-27', 'scholarship', null, 'Priority deadline for automatic international admission scholarships (fall 2027)', '2027-05-31', 'The scholarships page lists ''May 31 (Fall)'' with no year, treated as fall 2027. No separate scholarship application is needed.', '258cf4f6-f744-52e6-96fd-ce158a5b94f5');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('d8057782-44e3-5e2c-998a-2f53fcba2556', 'required_nonnative', 'Applicants from UCO''s approved native English-speaking countries are exempt. Alternative: 12 weeks of intensive English at an approved U.S. ESL program after reaching a minimum TOEFL 48 iBT (460 PBT), IELTS 5.0, PTE 36 or iTEP 3.0. Students below the test minimums can apply for conditional admission and attend an approved 12-week Oklahoma ESL program, such as The Language Company on UCO''s campus, before enrolling.', 'a2cac4a8-c2a9-5d42-99bb-ad6897899cfc');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
