insert into cost_aid (institution_id, year, tuition_intl_usd, room_board_usd, other_usd, total_coa_usd, intl_aid_policy, intl_need_aid, meets_full_need, merit_scholarships, merit_separate_app, notes, source_id) values
 ('d8057782-44e3-5e2c-998a-2f53fcba2556', '2026-2027', 19900, 10300, 2260, 32460, 'merit_only', false, false, true, false, 'International tuition page (undated, accessed 2026-10-26; labeled 2026-2027 as the current page): undergraduate tuition and fees $19,900 per year at 12 credit hours per semester, housing and dining $10,300 (nine months), books, insurance and miscellaneous $2,260 (in other_usd), total $32,460.; College Navigator 2024-25: tuition and fees in-state $8,818, out-of-state $19,704; on-campus food and housing $9,700, other $8,400; total_coa_usd is the out-of-state on-campus total.; Applying for admission also applies for automatic freshman scholarships: Distinguished Global Scholar up to $16,000 over four years ($4,000/yr) for GPA 3.50 or SAT 1300 or ACT 28; Merit Global Scholar up to $12,000 ($3,000/yr) for GPA 3.25 or SAT 1250 or ACT 26; Honor Global Scholar up to $8,000 ($2,000/yr) for GPA 3.00 or SAT 1200 or ACT 24. Renewable with a 3.00-3.25 GPA. Extra funding (up to $4,500/yr total) for residents of Nigeria, Ghana, Malaysia, Vietnam, Thailand or Ivory Coast. UCO says it awards about $700,000 a year to international students.', 'b6b6f6c8-b88e-54fa-ac0c-8ad2da43cade');
