insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('869dac5f-e3ea-568c-9884-83ac4b395d73', '2026-27', 'optional', 'Test-optional extended through the fall 2027 entry term; CMC will return to test-required for fall 2028. Superscoring across sections within one test type. Enrolling students who submitted scores must send official scores before fall classes begin.', '1ad7e78b-a794-546b-8d57-49ed83e89b7c');
insert into application_requirements (institution_id, cycle, platforms, supplemental_essays, teacher_recs, counselor_rec, interview, app_fee_usd, css_profile_required, notes, source_id) values
 ('869dac5f-e3ea-568c-9884-83ac4b395d73', '2026-27', array['common_app','coalition']::text[], true, 1, true, 'optional_evaluative', 70, true, 'Two required supplemental essays (Common and Coalition) plus an optional 2-minute video response. One teacher recommendation from a core academic subject. Interview is not required but highly recommended and is part of the evaluation; ED I applicants should interview by mid-November. CSS Profile + FAFSA are required only when applying for aid, and CMC does not accept the CSS Profile or IFSAA from international applicants (it uses its own international aid form).', '1ad7e78b-a794-546b-8d57-49ed83e89b7c');
