insert into cost_aid (institution_id, year, tuition_usd, room_board_usd, books_usd, other_usd, total_coa_usd, intl_aid_policy, intl_need_aid, meets_full_need, merit_scholarships, notes, source_id) values
 ('869dac5f-e3ea-568c-9884-83ac4b395d73', '2023-2024', 72120, 22190, 1200, 1500, 91510, 'need_aware_full_need', true, true, true, 'College Scorecard (IPEDS 2023-24): tuition includes required fees; on-campus cost of attendance.; Need-aware for all international applicants; if admitted, CMC commits to meeting demonstrated need as determined at admission. Applicants must request aid on the application and submit the CMC Financial Aid Application for International Students (IFSAA and CSS Profile not accepted). Students not receiving aid at admission are not eligible later. Merit scholarships are available to first-year applicants (priority: application by Dec 1), no separate application.', '26d0a39f-6819-5751-92ee-d7e19c83a621');
