insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, gpa_avg, pct_reporting_gpa, gpa_distribution, notes, source_id) values
 ('f3343b57-3aa7-595f-a784-3933c99db9d2', '2025-2026', 38365, 34004, 5376, 3.7, 99.9, '{"4.0": 29.9, "3.75-3.99": 18.4, "3.50-3.74": 16.6, "3.25-3.49": 15.1, "3.00-3.24": 12.1, "2.50-2.99": 7.7, "2.0-2.49": 0.1}'::jsonb, 'CDS C1/C11/C12 (fall 2025 entering class). CSU does not consider SAT/ACT scores, so C9 percentiles are not reported. CDS gives no residency or international split for applicants/admits (C1 says N/A). Student-faculty ratio is I-2 (fall 2024, 17 to 1). Undergrad enrollment is the B1 total (26,490); the international count is the B2 nonresident total (657). No waitlist; early action only (no early decision).', 'b128fa85-c05b-5697-9d66-e313e267aee7');
