insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, gpa_avg, pct_reporting_gpa, gpa_distribution, notes, source_id) values
 ('9ec622d0-627a-5f9a-ae04-95aa87aba48e', '2024-2025', 33350, 30842, 5543, 3.33, 100.0, '{"4.0": 11.64, "3.75-3.99": 11.85, "3.50-3.74": 15.64, "3.25-3.49": 16.38, "3.00-3.24": 17.72, "2.50-2.99": 22.5, "2.0-2.49": 3.82, "1.0-1.99": 0.45}'::jsonb, 'CDS C1 fall 2024 first-year class: applicants = 15,130 men + 18,122 women + 98 another gender; admits = 13,821 + 16,929 + 92. Enrolled 5,543 is the full-time plus part-time total in C1 and B1 (2,578+34 men, 2,875+37 women, 19 another gender); C1''s separate enrolled-by-gender lines add to a lower 4,655, an inconsistency in the CSUN file. CSUN left the C1 residency breakdown (in-state, out-of-state, international) blank, so international applicants and admits are null; 125 first-time first-year students and 950 degree-seeking undergraduates were nonresidents (B2). SAT/ACT score ranges (C9) are blank and the C7 factor check boxes could not be read reliably, so scores and factors are omitted. CSU campuses are test-blind. College Navigator (IPEDS) shows 33,005 applicants and 93% admitted for fall 2024.', '580222e7-6156-5c15-addc-820c19222352');
insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('9ec622d0-627a-5f9a-ae04-95aa87aba48e', '2026-27', 'blind', 'The CSU system no longer uses SAT/ACT in admission decisions; College Navigator (IPEDS fall 2024 admissions) lists SAT/ACT as ''Not considered (Test Blind)''. CSUN''s own CDS C8A check box could not be read reliably. Eligibility for international freshmen is based on a converted GPA of 3.0 or higher.', '6f96e30d-38ee-5fa6-862c-8a1fcd163f0b');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('9ec622d0-627a-5f9a-ae04-95aa87aba48e', '2026-27', array['own']::text[], 70, 'Apply through Cal State Apply (not the Common App); the $70 fee is payable only by credit or debit card. Needs a converted GPA of 3.0+ (4.0 scale). Documents: official transcripts and diplomas with certified English translations, Affidavit of Financial Support plus bank statement, passport photo page, English test results. College Navigator shows essays and recommendations are not considered. Impacted majors (Music, Cinema and Television Arts production options) have earlier closing dates.', 'e7383038-a244-5545-ba9d-4edf35abbac0');
insert into deadlines (id, institution_id, cycle, kind, label, due_date, notes, source_id) values
 ('373ad571-bd09-5e13-93a1-fd3c5f02c3d5', '9ec622d0-627a-5f9a-ae04-95aa87aba48e', '2026-27', 'application', 'International first-year application deadline, Cal State Apply (fall 2027)', '2027-05-15', 'Fall 2027 filing period is Aug 1, 2026 to May 15, 2027 (the page does not repeat the year; treated as 2027). Impacted majors close earlier: Music Jan 15, 2027; Cinema and Television Arts Film Production and Television Production Jan 31, 2027. CSUN notes international applicants may have different deadlines from domestic ones.', 'c41605ea-dfd9-5e36-a3e6-a9fef0dbdd34'),
 ('bfcc294e-b37a-5649-9670-46dc8fdb5bd8', '9ec622d0-627a-5f9a-ae04-95aa87aba48e', '2026-27', 'other', 'International document deadline (fall applicants)', '2027-06-15', 'Page gives ''June 15'' for fall international document deadlines without a year; treated as 2027.', 'c41605ea-dfd9-5e36-a3e6-a9fef0dbdd34'),
 ('6d55865a-c7b4-5634-9326-776ab2fe1c27', '9ec622d0-627a-5f9a-ae04-95aa87aba48e', '2026-27', 'deposit', 'Intent to Enroll deadline (fall applicants)', '2027-05-01', 'If admitted after May 1, submit intent within two weeks of the admission date.', 'c41605ea-dfd9-5e36-a3e6-a9fef0dbdd34');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('9ec622d0-627a-5f9a-ae04-95aa87aba48e', 'required_nonnative', 'Not required with 3+ years at a U.S. high school or 3+ years at a high school where English was the principal language of instruction (listed countries: Australia, Belize, Canada, England, Ireland, New Zealand, Northern Ireland, Scotland, Wales, Antigua and Barbuda, Bahamas, Cayman Islands, Trinidad and Tobago). TOEFL ITP is not accepted. Also accepted: iTEP Academic 3.8, GTEC CBT 1125, EIKEN CSE 2304 (Pre-1).', 'e7383038-a244-5545-ba9d-4edf35abbac0');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select '9ec622d0-627a-5f9a-ae04-95aa87aba48e'::uuid, 'required_option', 'e7383038-a244-5545-ba9d-4edf35abbac0'::uuid, v.* from (values
 ('TOEFL_IBT', 61, 'Exams on the old 0-120 scale. Paper-based minimum 500. Send scores to CSUN school code 4707.'),
 ('TOEFL_IBT_2026', 3.5, 'New iBT (1-6 scale). The page lists ''New iBT: 3.5'' and does not define the scale.'),
 ('IELTS', 6.0, 'IELTS Academic; have IELTS send the Test Report Form to CSUN.'),
 ('DUOLINGO', 95, 'Send through your Duolingo account.'),
 ('PTE', 50, 'PTE Academic; send online through your PTE account.'),
 ('CAMBRIDGE', 172, 'C1 Advanced (CAE); email the ''Confirmation of Entry'' page to intladm@csun.edu.')) v;
insert into score_codes (institution_id, test_key, code, notes, source_id) values
