 ('TOEFL_IBT', 79, '{"reading": 8, "listening": 7, "speaking": 18, "writing": 16}'::jsonb, 'University minimum for all undergraduate programs except Nursing.', '8be598d7-5359-5d69-b6ce-5e0444b58f7b'::uuid),
 ('TOEFL_IBT_2026', null, null, 'The pages do not print a full-admission minimum on the new 1-6 scale (tests from Jan. 21, 2026); only the LynxDirect pathway value of 3.5 is listed, so no minimum is recorded.', '9a2eceb5-4e28-5c58-a315-2ad7585db3d0'::uuid),
 ('IELTS', 6.5, '{"each_section": 5.5}'::jsonb, 'IELTS Academic.', '8be598d7-5359-5d69-b6ce-5e0444b58f7b'::uuid),
 ('DUOLINGO', 105, '{"each_section": 85}'::jsonb, 'Minimum 85 on each of Literacy, Conversation, Comprehension and Production; official score through the Duolingo website.', '8be598d7-5359-5d69-b6ce-5e0444b58f7b'::uuid),
 ('PTE', 58, '{"each_section": 42}'::jsonb, 'PTE Academic.', '8be598d7-5359-5d69-b6ce-5e0444b58f7b'::uuid)) v;
