insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('cb7a90c7-d930-51aa-a6df-5f58830558c6', '2026-27', 'required', 'Required by Florida Board of Governors rule for all Florida public universities: first-year applicants must submit an SAT, ACT or CLT score (ACT Science no longer needed from the 2025-26 cycle). Middle 50% of admitted first-years: SAT 1090-1270, ACT 22-28, GPA 3.66-4.29 (recalculated on academic core courses). Students admitted without scores are not eligible for merit scholarships.', 'f8230c40-d846-5b84-9579-dc9521db5b8c');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('cb7a90c7-d930-51aa-a6df-5f58830558c6', '2026-27', array['common_app']::text[], 30, 'International applicants apply through the Common App with a $30 non-refundable fee. High school records from non-U.S. curricula must be evaluated by a NACES agency (course-by-course list, overall U.S. GPA and a separate math GPA). 18 high school units (4 English, 4 math, 3 science, 3 social science, 2 foreign language, 2 electives). Essays and recommendations are not mentioned on these pages.', 'f0b207fb-a668-59fe-afba-c5a8331de4d5');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notification_date, notes, source_id) values
 ('026c422f-9647-5bcb-9fb4-08c97e5780a0', 'cb7a90c7-d930-51aa-a6df-5f58830558c6', '2026-27', 'application', 'EA', 'Early Action application deadline (summer/fall 2027 entry)', '2026-10-15', '2026-12-04', 'Dates print without a year; treated as fall 2027 entry. Materials due Oct 22, last scores considered Nov 20; outcomes are admit, defer or deny. Nursing BSN direct admit and Pre-Architecture also use Oct 15 (complete by Jan 15).', '68231231-efa0-5721-9cef-9624ee142162'),
 ('174ca5bb-6682-589e-9e0a-7202847d680d', 'cb7a90c7-d930-51aa-a6df-5f58830558c6', '2026-27', 'application', 'ROLLING', 'Rolling Decision application and materials deadline (summer/fall 2027 entry)', '2027-03-12', null, 'Decisions are issued about four weeks after the file is complete (International deadlines page). Outcomes: admit, defer, deny or waitlist. FAU may offer a different entry term than requested.', 'dc76150d-8e91-58ea-809a-8c4ceb4667ff'),
 ('7e780083-0cd8-5148-8e57-47db23177118', 'cb7a90c7-d930-51aa-a6df-5f58830558c6', '2026-27', 'scholarship', null, 'Freshman merit scholarship automatic consideration; President''s International Scholarship priority', '2027-01-15', null, 'International President''s Scholarship ($6,000) priority deadline Jan 15, regular Mar 15 for fall.', '2c560c03-ce2a-5ab7-949c-4e1a995c70da'),
 ('dcaeca61-d6a5-5196-a38a-6793c6df8873', 'cb7a90c7-d930-51aa-a6df-5f58830558c6', '2026-27', 'deposit', null, 'Freshman admissions deposit (fall)', '2027-05-01', null, null, '68231231-efa0-5721-9cef-9624ee142162');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('cb7a90c7-d930-51aa-a6df-5f58830558c6', 'required_nonnative', 'Exempt if SAT EBRW is at least 490 or ACT Reading 19 and English 17 (Florida BOG college-readiness minimums), or with 3 years of secondary education in English-medium instruction (U.S. or abroad, or in a majority-English country), 30 post-secondary credits including ENC 1101/1102 with C or better, or 60+ post-secondary credits. Also accepted: HKDSE 5, IGCSE English C/4, IB English HL 6, ELS 112, OHLA Elite, Study Group 65%, FAU Intensive English Institute Level VI. Below the minimum: the Conditional Admissions Track (CAT) lets students complete the FAU Intensive English Institute''s Global Academic Track (Level 6) instead of submitting TOEFL or IELTS.', 'cefcc3d6-a4e2-5a91-9c20-0e5b62e4c6fa');
