insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('896861bc-d8aa-5153-8b28-3fbed6e8adae', 'required_nonnative', 'Students whose first language is not English must submit a test or complete the English Language Proficiency Test Waiver Request Form in the applicant portal after submitting. Official scores must be under 2 years old. Applicants in the NYC area may alternatively take Fordham''s ESL placement evaluation (FELT).', '14f94656-0d8b-56d2-ae47-1593504807e7');
