insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, notes, source_id, source_note) values
 ('db08fb59-16b9-5166-bfe2-2d6be839012e', '2023-2024', 20201, 19469, 3661, 'Baseline from IPEDS (fall 2023 first-time, first-year class); College Navigator also shows fall 2024: 21,521 applicants, 95% admitted, 18% of admitted students enrolled (percentages are rounded). Fresno State''s Common Data Sets are available only by emailing oie@mail.fresnostate.edu (academics.fresnostate.edu/oie/data/common.html), so none was read. Undergraduate enrollment and international (nonresident) undergraduates are IPEDS fall 2023 totals. Applications by residency (international applicants and admits), GPA and score ranges are not in IPEDS, so they are left null. The CSU is test-blind, so no SAT/ACT percentiles are reported.', '8ff01ae3-bb31-57d2-bf40-6f18404b1571', 'admissions_site');
insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('db08fb59-16b9-5166-bfe2-2d6be839012e', '2026-27', 'blind', 'The CSU system no longer uses SAT/ACT in admission decisions; College Navigator (IPEDS fall 2024 admissions) lists SAT/ACT as ''Not considered (Test Blind)''. SAT Reading and Writing 550 or ACT English 22 only count as proof of English proficiency on Fresno State''s international page. The page states no minimum GPA.', '8a0f06b8-36c0-5549-85c1-13b606bc000f');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('db08fb59-16b9-5166-bfe2-2d6be839012e', '2026-27', array['own']::text[], 70, 'Apply through Cal State Apply (a paper application is also offered) with a $70 fee; email unofficial documents to intladmissions@csufresno.edu. Documents: transcripts or mark sheets with English translation, graduation certificate, passport page, and financial documents plus an Affidavit of Support (these two may be sent after admission). A personal statement is encouraged but not required; recommendations are optional. The page does not state a minimum GPA or course pattern.', '7c0348db-f9fc-52c4-8f01-d634a0f4d367');
insert into deadlines (id, institution_id, cycle, kind, label, due_date, notes, source_id) values
 ('94931589-8cff-517d-9658-aacb9159ac82', 'db08fb59-16b9-5166-bfe2-2d6be839012e', '2026-27', 'application', 'Fall international application deadline, applicants outside the U.S.', '2027-07-01', 'Applications open Aug 1. The page prints no year; treated as fall 2027. Consideration after the deadline is not guaranteed.', '7c0348db-f9fc-52c4-8f01-d634a0f4d367'),
 ('4cd2fb9c-49b1-54b5-b0a1-f337d6db63dd', 'db08fb59-16b9-5166-bfe2-2d6be839012e', '2026-27', 'application', 'Fall international application deadline, applicants already in the U.S.', '2027-08-01', 'Opens and closes Aug 1. The page prints no year; treated as fall 2027.', '7c0348db-f9fc-52c4-8f01-d634a0f4d367'),
 ('82ade23c-a135-5870-86f3-5513814e13b4', 'db08fb59-16b9-5166-bfe2-2d6be839012e', '2026-27', 'scholarship', 'Muhareb Family Grant expression of interest (fall 2027)', '2027-05-15', 'Letter of interest for newly admitted international students; no separate application.', '9176ca39-ec7c-5678-a6da-3e98175b5ce4');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('db08fb59-16b9-5166-bfe2-2d6be839012e', 'required_nonnative', 'Waived for students who studied 3+ years in U.S. high schools, or 3 years of full-time academic study in listed English-instruction countries/regions (Australia, Canada [Quebec needs English demonstration], Ireland, New Zealand, UK, many Caribbean and African countries). Other accepted proofs: SAT Reading and Writing 550, ACT English 22, AP English Language or Literature 3, IB English A HL 4, GTEC 1095, iTEP 3.6, Eiken Pre-1, ELS 112, FLS 16, TLC 9, Fresno State American English Institute Advanced Level.', '7c0348db-f9fc-52c4-8f01-d634a0f4d367');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select 'db08fb59-16b9-5166-bfe2-2d6be839012e'::uuid, 'required_option', '7c0348db-f9fc-52c4-8f01-d634a0f4d367'::uuid, v.* from (values
 ('TOEFL_IBT_2026', 3.5, 'New TOEFL iBT, exams starting Jan 21, 2026 (1-6 scale).'),
 ('TOEFL_IBT', 61, 'Institutional code 4312.'),
 ('IELTS', 6.0, 'Page text: ''6.0 or with 5.5 band score in each section''.'),
 ('DUOLINGO', 100, null),
 ('PTE', 45, 'Pearson''s Test of English.')) v;
insert into score_codes (institution_id, test_key, code, notes, source_id) values
 ('db08fb59-16b9-5166-bfe2-2d6be839012e', 'toefl', '4312', 'Fresno State institutional code for English test scores.', '7c0348db-f9fc-52c4-8f01-d634a0f4d367');
insert into cost_aid (institution_id, year, tuition_intl_usd, room_board_usd, other_usd, total_coa_usd, meets_full_need, merit_scholarships, notes, source_id) values
 ('db08fb59-16b9-5166-bfe2-2d6be839012e', '2027-2028', 20979, 11634, 2978, 35591, false, true, 'Fresno State''s estimate for Fall 2027/Spring 2028 (undergraduate, 12 units a semester): tuition and fees $20,979 (one combined figure), food and housing $11,634, books and insurance $2,978 (other), total $35,591. The Fall 2026/Spring 2027 estimate is $34,434. International students must buy the university-approved insurance.; Dean''s Scholarship Tuition Waiver for international students and out-of-state residents, about $1,250 to $3,750 each (70+ international students received one last year). Muhareb Family Grant: $1,000 to $1,500 for a select group of newly admitted international students in their first semester, chosen on academic achievement, financial need and funding; no application, but send an expression of interest by May 15, 2027 (fall 2027). Conditional admission: students without a qualifying TOEFL/IELTS can be admitted to ESL plus a degree program (two-year language-study I-20, American English Institute on campus); placement needs one score report with no minimum. Same fall deadlines (July 1 outside the U.S., Aug 1 in the U.S.).', 'd79e345e-4f87-50f9-b2d2-31a16e2f8be4');
