insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('301a78d8-1851-554b-8cea-bbdf8bb12255', '2026-27', 'optional', 'SAT/ACT are not required for international applicants educated abroad, but a 1200+ SAT or 25+ ACT composite automatically counts as meeting the 3.0 GPA requirement, and SAT/ACT is required to qualify for the automatic Excellence awards (President''s and Dean''s).', '6f9a8f3d-8148-5e8e-b65d-e6c024ec5087');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('301a78d8-1851-554b-8cea-bbdf8bb12255', '2026-27', array['common_app','own']::text[], 65, 'Formula-style admission: international first-years need a high school GPA equivalent to 3.0/4.0 (or SAT 1200+/ACT 25+) plus core courses (4 English, 3 math incl. algebra and geometry, 3 science incl. 2 lab, 2 social studies). Rolling admission with no closing date; apply 6-8 weeks before needed for the I-20/visa. No essays, recommendations or merit certificates are required. $65 fee, no waiver. Bank statement or sponsor letter required ($52,000 for most majors, $54,300 for Design and Animal Enterprise and Innovation per the requirements page; another Iowa State page shows $49,300). Official English test results may arrive up to 30 days after the deadline.', 'c74ebca9-7366-5bad-b240-9a083c9c3e88');
insert into deadlines (id, institution_id, cycle, kind, label, due_date, notes, source_id) values
 ('a7d3ac90-2568-5173-b2aa-59cb8772f378', '301a78d8-1851-554b-8cea-bbdf8bb12255', '2026-27', 'scholarship', 'International Merit Scholarship priority deadline (fall 2027)', '2027-02-15', 'Priority date for the OneApp International Merit Scholarship application (page prints no year; taken as the fall 2027 cycle) (Award of Achievement up to $40,000; Award of Distinction up to $16,000). Admission itself is rolling with no application closing date.', 'a0f7a0e3-a516-55f2-9c27-cee33a1b9963'),
 ('8297e8ba-84ce-5301-9b72-793220d4962f', '301a78d8-1851-554b-8cea-bbdf8bb12255', '2026-27', 'deposit', 'Accept offer of admission (fall); final International Merit Scholarship date', '2027-05-01', 'Accepting by May 1 is required for the automatic International Student Excellence Award and for the Merit Scholarship.', 'a0f7a0e3-a516-55f2-9c27-cee33a1b9963');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('301a78d8-1851-554b-8cea-bbdf8bb12255', 'required_nonnative', 'Waived for native English speakers residing in a country where English is a primary official language, graduates of U.S. high schools, and those with a B or higher in the equivalent of Iowa State''s English 1500 or 2500 at an accredited U.S. college. Alternatives to a test: SAT EBRW 460, ACT English 19, IB English 5, AP English Language 3 or Literature 4, IGCSE/O-Level D in First Language English or C in ESL. IELTS One Skill Retake and TOEFL MyBest scores are not accepted. No conditional admission or ESL pathway program is described on the international admissions pages reviewed.', 'aa74600b-b980-5dc2-b0ea-89e21237665e');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, min_subscores, notes)
select '301a78d8-1851-554b-8cea-bbdf8bb12255'::uuid, 'required_option', 'aa74600b-b980-5dc2-b0ea-89e21237665e'::uuid, v.* from (values
 ('TOEFL_IBT', 71, '{"speaking": 17, "writing": 17}'::jsonb, '71 iBT with at least 17 on Speaking and Writing (exams taken before 2026-01-21).'),
 ('TOEFL_IBT_2026', 4.0, '{"each_section": 3.5}'::jsonb, '4.0 with a minimum band of 3.5 on the 6.0 scale (exams from 2026-01-21).'),
 ('IELTS', 6.0, '{"each_section": 5.5}'::jsonb, '6.0 overall with all subscores 5.5 or above; One Skill Retake not accepted.'),
 ('DUOLINGO', 105, null, 'Minimum Duolingo English Test score is 105.'),
 ('PTE', 48, null, '48 overall.')) v;
