insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('907386ed-a5b4-53d3-92e0-6ec7d55d8e88', '2026-27', 'optional', 'SAT/ACT are not required for admission; they are considered if submitted and used for placement. The international application says to check the requirements of your school, since some programs may ask for a score.', '85044ead-a674-56e7-a3dc-32f609fc2fcb');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('907386ed-a5b4-53d3-92e0-6ec7d55d8e88', '2026-27', array['own']::text[], 90, 'International admission standard: minimum 2.5 GPA on a 4.0 scale for all previous coursework, plus proof of high school graduation for your country. $90 fee payable by credit card; it cannot be waived and the Common App fee waiver is not accepted. English scores must be submitted with the application, but no minimum English score is required for admission; applicants who do not meet full English proficiency can be admitted and take Applied English Center (AEC) courses. Academic records can be unofficial at application; official copies are needed before enrolling. Applicants with a gap of more than three months after high school need a short gap statement.', '85044ead-a674-56e7-a3dc-32f609fc2fcb');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('5c5fd0a0-e599-55f7-bf39-7f5dd55507fb', '907386ed-a5b4-53d3-92e0-6ec7d55d8e88', '2026-27', 'application', 'ROLLING', 'Fall application deadline for students outside the U.S.', '2027-05-01', 'The page prints no year; taken as fall 2027. Spring deadline is Nov. 15. Students inside the U.S. have a July 25 fall deadline.', '85044ead-a674-56e7-a3dc-32f609fc2fcb'),
 ('273ad880-eed4-5ab2-aee5-da105de966b4', '907386ed-a5b4-53d3-92e0-6ec7d55d8e88', '2026-27', 'scholarship', null, 'Fall scholarship application deadline (complete application by this date)', '2027-05-01', 'The KU CDS (C14) separately lists Dec. 1 as the priority date for institutional scholarships.', '2de23637-56b9-503a-a437-60dbdfeb20aa');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('907386ed-a5b4-53d3-92e0-6ec7d55d8e88', 'required_nonnative', 'A score or other proof must be submitted with the application, but a minimum is not required for admission. Applicants below the minimums take the online AEC Proficiency Test; those who pass can enroll full time in their degree, others enroll in the Applied English Center (concurrently or beforehand). Exempt: native English speakers; four years of college-prep English and a 2.5+ GPA from a qualifying English-speaking region or U.S.-accredited school; B or better in College English Composition 1 and 2 with 24+ credit hours; full IB diploma with English HL 5+; U.S. associate degree with a 2.5+ GPA. Also accepted: SAT EBRW 590, ACT English+Reading 48, AP English 4, A-level English grade B on both exams, TOEFL paper 60. Scores must be under two years old.', 'bee2c222-ed72-5359-96a3-7fc37671271b');
insert into english_requirements (institution_id, source_id, test_key, status, min_total, min_subscores, notes)
select '907386ed-a5b4-53d3-92e0-6ec7d55d8e88'::uuid, 'bee2c222-ed72-5359-96a3-7fc37671271b'::uuid, v.* from (values
 ('TOEFL_IBT', 'required_option', 79, '{"each_section": 18}'::jsonb, 'Minimum for full-time degree coursework (not an admission minimum); iBT or Special Home Edition, scale before 2026-01-21.'),
 ('TOEFL_IBT_2026', 'required_option', 4.5, '{"each_section": 4}'::jsonb, 'Tests from 2026-01-21 on the 1-6 scale.'),
 ('IELTS', 'required_option', 6.5, '{"each_section": 6.0}'::jsonb, 'IELTS Academic; minimum for full-time degree coursework.'),
 ('PTE', 'required_option', 53, '{"each_section": 48}'::jsonb, 'PTE Academic.'),
 ('DUOLINGO', 'accepted', null, null, 'For students with limited access to testing: scores can be shared through Duolingo for the application, but these students must still take the AEC test. No minimum is printed.')) v;
