insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, tuition_intl_usd, required_fees_usd, room_board_usd, books_usd, intl_aid_policy, intl_need_aid, intl_need_aid_awarded, intl_avg_award_usd, meets_full_need, merit_scholarships, notes, source_id) values
 ('907386ed-a5b4-53d3-92e0-6ec7d55d8e88', '2025-2026', 11298, 30177, 30177, 1155, 11798, 1224, 'merit_only', false, 330, 12572, false, true, 'CDS G1 (2025-26): out-of-state tuition is also paid by international students. H6 (final AY2025): only institutional non-need-based aid (International Admissions Scholarships); 330 international undergraduates received aid, averaging $12,572 ($4,148,695 total). The international admissions cost page (year not printed) estimates $33,854 tuition and fees plus $18,424 living expenses = $52,278 per year. Course fees vary by school.; Renewable freshman scholarships based on high school GPA alone, available to international students (up to $64,000 over a KU career): KU Excellence 3.95-4.00 GPA $16,000/yr; Distinction 3.85-3.94 $14,000/yr; Achievement 3.70-3.84 $12,000/yr; Performance 3.50-3.69 $10,000/yr; Access 3.25-3.49 $8,000/yr. Renewal needs a 3.0 KU GPA and full-time enrollment; first bachelor''s degree or eight semesters. Apply for admission by May 1 to be considered.', 'd2d94904-8d37-534f-9daf-fc3550013cc8');
