insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, pct_submit_sat, pct_submit_act, notes, source_id, source_note) values
 ('cedc6699-7f2c-5649-b7b2-c405783ac973', '2023-2024', 12142, 9335, 1968, 1, 0, 'Baseline from IPEDS (fall 2023 entering class); no Common Data Set was found on Kean''s Institutional Research pages, so GPA, residency and international applicant splits are not available. College Navigator (fall 2024): 13,936 applicants, 76% admitted, 19% of admits enrolled. SAT/ACT percentiles are omitted because only about 1% of enrolled first-years submitted SAT scores (10 students in fall 2023). Undergraduate enrollment 11,234 and 682 nonresident-alien undergraduates are IPEDS fall 2023 (full-time plus part-time). Kean merged with New Jersey City University on July 1, 2026; these figures predate the merger.', '4fe23575-601c-5bc0-982f-189ab1472124', 'admissions_site');
insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('cedc6699-7f2c-5649-b7b2-c405783ac973', '2026-27', 'optional', 'Test-optional for first-year applicants with a high school GPA of 3.0 or higher and at least 16 college-preparatory courses; home-schooled, online high school and GED applicants must submit scores. The test-optional page does not address international applicants. If sent, Kean superscores SAT (highest ERW and Math) and uses the highest ACT composite. Test-optional admits still take placement tests and are not eligible for merit scholarships.', 'fdfd5c69-dbfc-5429-b4ab-a780af317d57');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('cedc6699-7f2c-5649-b7b2-c405783ac973', '2026-27', array['common_app','own']::text[], 75, 'International applicants submit a course-by-course transcript evaluation (including GPA) from a NACES-affiliated agency. Two English-language recommendation letters and a 1-2 page personal essay are recommended on the international page; the test-optional page lists a transcript, two letters, an essay and an activities list as required for test-optional applicants. A promo code waiving the $75 fee is available by attending a virtual information session.', 'e35c1522-db6c-5b69-9155-eda595143d11');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('4d8c9e58-829a-507d-a52b-15cd4ead76ff', 'cedc6699-7f2c-5649-b7b2-c405783ac973', '2026-27', 'priority', 'ROLLING', 'Preferred international freshman application deadline (fall 2027)', '2027-04-30', 'Applications are accepted on a rolling basis after this date. The FAQ prints no year; taken as fall 2027.', '18b1d0bf-3837-5a5d-9ad9-1b9368c75e16'),
 ('94474621-d7ad-52eb-91da-3426eff12678', 'cedc6699-7f2c-5649-b7b2-c405783ac973', '2026-27', 'application', null, 'Architectural Studies (B.A.) international freshman deadline', '2027-02-15', null, '18b1d0bf-3837-5a5d-9ad9-1b9368c75e16'),
 ('a5a256c2-3ac9-54fb-8cae-82f58a8646ae', 'cedc6699-7f2c-5649-b7b2-c405783ac973', '2026-27', 'deposit', null, 'Preferred tuition deposit deadline', '2027-05-01', null, '18b1d0bf-3837-5a5d-9ad9-1b9368c75e16');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('cedc6699-7f2c-5649-b7b2-c405783ac973', 'required_nonnative', 'Required if secondary education was in a non-English-primary country. A waiver can be requested with official documentation that secondary school instruction was in English; applicants to fully online programs are not eligible. Scores must be from the past two years and sent directly by the testing agency. Kean has no ESL program; the SUPERA Spanish-speaking program lets freshmen take general education courses in Spanish while completing ESL requirements and has no English test or SAT requirement.', 'e35c1522-db6c-5b69-9155-eda595143d11');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select 'cedc6699-7f2c-5649-b7b2-c405783ac973'::uuid, 'required_option', 'e35c1522-db6c-5b69-9155-eda595143d11'::uuid, v.* from (values
 ('TOEFL_IBT', 79, 'Paper-based minimum 550.'),
 ('TOEFL_IBT_2026', 4, 'Exams taken after Jan 21, 2026: the page prints ''a minimum total score of 4'' without naming the scale (presumably the new 1-6 scale); confirm with admissions.'),
 ('IELTS', 6.0, null),
 ('DUOLINGO', 105, null)) v;
