insert into deadlines (id, institution_id, cycle, kind, label, due_date, notes, source_id) values
 ('9738f74d-954a-5b33-9851-d738318b03b0', '5e1b1341-fe14-595f-b676-31e917e3472d', '2026-27', 'priority', 'Priority deadline, fall 2027 (August start), international', '2026-12-01', 'The page prints ''December 1 for Fall semester (August start)'' and no year, so it is taken as the current cycle; spring priority is Oct. 15. The freshman scholarship deadline is also Dec. 1 and funds can run out earlier.', '3fa3f4b8-5208-522f-acd4-f0fd87da4040'),
