insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('b32a563a-004e-5775-bfaf-f40885be3093', '2026-27', 'optional', 'Lehigh "has adopted a test-optional policy regarding submission of SAT or ACT scores indefinitely." Scores are considered only if the applicant chooses to report them; official scores must reach Lehigh before the first day of classes. SAT/ACT are superscored.', '0e1d892d-e257-5615-bc74-cdcf5283c907');
insert into application_requirements (institution_id, cycle, platforms, supplemental_essays, teacher_recs, counselor_rec, interview, app_fee_usd, notes, source_id) values
 ('b32a563a-004e-5775-bfaf-f40885be3093', '2026-27', array['common_app','coalition']::text[], true, 1, true, 'optional_evaluative', 75, 'Common App or Coalition (Scoir) application with the Lehigh Questions and Writing Supplement; School Report with counselor recommendation and official transcript; one teacher recommendation; mid-year school report. Interviews are not required, but "all interviews are evaluative and become part of your application." Non-U.S. citizens who will need aid must submit the CSS Profile (or ISAFA if the $25 fee is a hardship) by the application deadline; other non-citizens need no Certificate of Finances at application. Fee waiver for hardship available to non-citizens by request.', '0e1d892d-e257-5615-bc74-cdcf5283c907');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('f094f211-204a-551d-912b-19fe82ea0278', 'b32a563a-004e-5775-bfaf-f40885be3093', '2026-27', 'application', 'ED', 'Early Decision I', '2026-11-01', 'Binding. Decision date "Mid December" (no fixed date published). Aid applicants send CSS Profile and tax forms by Nov 1.', 'ba367a6b-f9b3-5863-8914-a6e2c4eddca7'),
 ('b0c69926-4d84-534f-ae06-89f30b17093d', 'b32a563a-004e-5775-bfaf-f40885be3093', '2026-27', 'application', 'ED2', 'Early Decision II', '2027-01-01', 'Binding. Decision date "Mid February" (no fixed date published). Aid applicants send CSS Profile and tax forms by Jan 15.', 'ba367a6b-f9b3-5863-8914-a6e2c4eddca7'),
 ('f5af99de-2a00-5d56-8b54-6393962352c0', 'b32a563a-004e-5775-bfaf-f40885be3093', '2026-27', 'application', 'RD', 'Regular Decision', '2027-01-01', 'Decision date "Late March" (no fixed date published). The page states no entry year; treated as the 2026-27 cycle (Fall 2027 entry). Lehigh has no Early Action.', 'ba367a6b-f9b3-5863-8914-a6e2c4eddca7');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('b32a563a-004e-5775-bfaf-f40885be3093', 'required_nonnative', 'Required unless the applicant''s first language is English or the last two full years of formal instruction (not counting the current year) were in English. TOEFL and IELTS are preferred; TOEFL iBT Home Edition and Duolingo are considered if those exams are unavailable. SAT/ACT cannot be used to meet the requirement. Scores must come directly from the testing agency.', '06ea2508-a306-5490-8c22-46eb8c6ad87c');
insert into english_requirements (institution_id, source_id, test_key, status, recommended_total, notes)
select 'b32a563a-004e-5775-bfaf-f40885be3093'::uuid, '06ea2508-a306-5490-8c22-46eb8c6ad87c'::uuid, v.* from (values
 ('TOEFL_IBT', 'required_option', 90, 'No hard minimum: "the most competitive candidates score above a 90". Page''s readiness bands: 95+ strong, 86-94 may need extra language support, 85 or below raises concern (tests before Jan 21, 2026).'),
 ('TOEFL_IBT_2026', 'required_option', 5.5, 'Page''s band for tests from Jan 21, 2026: 5.5+ strong readiness, 4.0-5.0 may need extra language support, 4.0 or below raises concern.'),
 ('IELTS', 'required_option', 7.0, 'No hard minimum: "the most competitive candidates score above" 7.0. Readiness bands: 7.5+ strong, 6.5-7.0 may need extra support, 6.0 or below raises concern.'),
 ('DUOLINGO', 'accepted', 120, 'Considered if TOEFL/IELTS are not available to the student. "Most competitive" at 120; readiness bands: 120+ strong, 110-119 may need extra support, 109 or below raises concern.')) v;
insert into cost_aid (institution_id, year, tuition_usd, room_board_usd, books_usd, other_usd, total_coa_usd, intl_aid_policy, intl_need_aid, meets_full_need, merit_scholarships, notes, source_id) values
 ('b32a563a-004e-5775-bfaf-f40885be3093', '2023-2024', 67920, 18180, 1000, 1500, 84497, 'need_aware_limited', true, false, true, 'College Scorecard (IPEDS 2023-24): tuition includes required fees; on-campus cost of attendance.; Lehigh has limited international financial aid and "is need-aware in the admissions process" for non-U.S. citizens; some applicants who apply for aid but show no need may be admitted without an aid offer. Aid packages range from a few thousand dollars to full tuition, room and board, with no additional aid after the initial offer. Merit scholarships range from $5,000 to full tuition with no separate application. CSS Profile required by the application deadline for any applicant who will need aid in any year.', '8b2045b9-8454-5a3b-9455-f769d9a9257c');
