insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('6bdf56a4-8bda-5a8b-852d-6cc43090159f', '2026-27', 'optional', 'Test scores are not required for an initial admission decision but are required for merit-based scholarships; when the GPA is not strong, scores can be used in the evaluation. International freshmen need a 2.5 GPA on the US scale; SAT EBRW 500 (or Accuplacer 250) is one way to show English proficiency. Policy 2306 lets out-of-state applicants qualify with ACT 26 / SAT 1240 or a core GPA of 3.0, or by meeting the in-state rule (core GPA 2.5, or ACT 23 / SAT 1130 with core GPA 2.0).', '6046109b-ccb9-5135-9b3c-258461159fa8');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('6bdf56a4-8bda-5a8b-852d-6cc43090159f', '2026-27', array['own']::text[], 20, 'The $20 fee is the CDS C13 figure (waivable); an older catalog listed $30 for international students, so confirm the current international fee. International applicants complete the online application and email all documents (PDF) to international@latech.edu, even when official copies are sent by the testing agency or school. Freshman requirement: 2.5 GPA converted to the US scale by Louisiana Tech''s admissions coordinator. An I-20 needs a bank statement or scholarship letter (not older than 6 months) covering a year of study. Louisiana Tech runs on the quarter system.', '1ffa8ac1-4dfe-5fd4-8d63-ebd7230247e8');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('f1c2e40b-7226-5568-b889-72884ed3dd57', '6bdf56a4-8bda-5a8b-852d-6cc43090159f', '2026-27', 'priority', null, 'Priority deadline for freshman admission scholarships (fall 2027 entry)', '2027-01-15', 'The scholarships page says to apply by Jan 15 of the senior year; the CDS (C14) lists Jan 1 as the priority date.', 'f2bd4efe-b409-5f2d-851a-f2f351a54355'),
 ('3c01c14e-6ee2-5016-9b89-ba3d682b95c0', '6bdf56a4-8bda-5a8b-852d-6cc43090159f', '2026-27', 'application', 'ROLLING', 'Application (fall 2027): no published closing date', null, 'CDS C14 states there is no application closing date and the current international page gives none; an older catalog asked for complete international applications two months before the first quarter. Apply as early as possible for I-20 and visa processing.', '1ffa8ac1-4dfe-5fd4-8d63-ebd7230247e8');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('6bdf56a4-8bda-5a8b-852d-6cc43090159f', 'required_nonnative', 'Proof of English proficiency can be a high school curriculum taught in English, SAT EBRW 500+, English Accuplacer 250+, or one of the tests below. Placing into regular English classes needs a 3.0 converted GPA, SAT EBRW 500+, Accuplacer 250+ or the language test (otherwise placement in the lowest level, with an option to test up).', '1ffa8ac1-4dfe-5fd4-8d63-ebd7230247e8');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select '6bdf56a4-8bda-5a8b-852d-6cc43090159f'::uuid, 'required_option', '1ffa8ac1-4dfe-5fd4-8d63-ebd7230247e8'::uuid, v.* from (values
 ('TOEFL_IBT', 79, 'Pre-2026 scale.'),
 ('TOEFL_IBT_2026', 4.5, 'The page prints ''TOEFL iBT (4.5, 79 pre-2026)''.'),
 ('IELTS', 6.5, null),
 ('DUOLINGO', 100, '105 is listed for the Bulldog Out-of-State Scholarship.'),
 ('PTE', 50, 'The page notes PTE is not currently accepted for the Bulldog Scholarship, although its scholarship criteria also list PTE 58.')) v;
insert into score_codes (institution_id, source_id, test_key, notes)
select '6bdf56a4-8bda-5a8b-852d-6cc43090159f'::uuid, '1ffa8ac1-4dfe-5fd4-8d63-ebd7230247e8'::uuid, v.* from (values
 ('sat', 'Louisiana Tech''s international pages give no SAT code; look it up in the College Board code search.'),
 ('act', 'Louisiana Tech''s international pages give no ACT code; look it up at act.org.'),
 ('toefl', 'No TOEFL code is listed; the page asks applicants to also email a PDF of the report to international@latech.edu.'),
 ('ielts', 'No institution code is listed on the international admissions page.'),
 ('duolingo', 'No institution code is listed on the international admissions page.'),
 ('pte', 'No institution code is listed on the international admissions page.')) v;
insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, required_fees_usd, room_board_usd, books_usd, intl_aid_policy, intl_need_aid, intl_merit_aid, meets_full_need, merit_scholarships, notes, source_id) values
 ('6bdf56a4-8bda-5a8b-852d-6cc43090159f', '2026-2027', 7010, 13751, 3724, 11487, 1641, 'merit_only', false, true, false, true, 'CDS G1 first-year figures. The international admissions page gives its own nine-month budget: tuition and fees $23,418 ($12,369 with the Bulldog Out-of-State Scholarship), living expenses $5,370, books and insurance $1,900, total $30,688 ($19,639 with the scholarship); no year is printed on that page. CDS H6 says non-need-based institutional aid is available to nonresidents but gives no counts or amounts.; The Bulldog Out-of-State Scholarship is an out-of-state tuition waiver worth about 50% of tuition costs (the international page''s example: tuition and fees $23,418 vs $12,369); recipients are treated as in-state for tuition. International freshmen need a 2.5 US-scale GPA, one admission test (TOEFL 4.5/79, IELTS 6.5, Duolingo 105, PTE 58, SAT 1130 or ACT 23), one English criterion (test, SAT English 500, ACT 23, Accuplacer 250) and one math criterion (SAT Math 510, Accuplacer 250 or a 3.0 GPA); keep a 2.0 quarterly GPA. Accept it in the application portal and upload the signed agreement. International students get no need-based aid.', '6106bd5e-dd9d-5fad-a9d7-7c06f15725fb');
insert into institution_tiers (institution_id, category_key, tier_code, rationale)
