insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('e8f004d9-e85d-584b-b179-48f5a2d4c46b', '2026-27', 'flexible', 'The testing page says UM requires SAT/ACT scores for Fall 2026 and the requirements page repeats that scores are required; self-reporting is allowed and official scores are needed only on enrollment. Applicants graduating from a high school or secondary school outside the United States may choose to apply with or without scores, as may Frost School of Music performance, BFA and School of Architecture applicants. The page does not state a separate rule for Fall 2027 entry.', '01f74aa6-35aa-584e-a7e5-3e74c6d36dbd');
insert into application_requirements (institution_id, cycle, platforms, supplemental_essays, interview, app_fee_usd, notes, source_id) values
 ('e8f004d9-e85d-584b-b179-48f5a2d4c46b', '2026-27', array['common_app']::text[], 0, 'optional_informational', 75, 'One letter of recommendation, from a counselor or a teacher. The requirements page says no supplemental essay is required. UM does not offer interviews, but international applicants may complete an optional InitialView interview (not rated or graded) by Jan 6. Frost School of Music Early Decision II and Regular Decision deadline is Dec 1 (earlier than below).', '29ef07f7-6f6d-551e-8873-4b06a14de564');
