insert into cost_aid (institution_id, year, tuition_intl_usd, room_board_usd, books_usd, other_usd, total_coa_usd, intl_aid_policy, meets_full_need, merit_scholarships, notes, source_id) values
 ('d088e912-36db-5e67-9974-b6dd0235848a', '2026-2027', 21013, 13658, 1500, 6000, 42171, 'merit_only', false, true, 'International bachelor cost page (9-month year; the page does not name the year, final figures are posted each July): tuition and fees $21,013 without the International Maverick Scholarship ($13,137 with it); housing and food $13,658; other $7,500 = $200 orientation fee + $1,500 books + $3,300 health insurance + $2,500 personal. Total $42,171 without / $34,295 with the scholarship. The page advises budgeting for at least an 8% increase.; All degree-seeking international bachelor''s students automatically receive the International Maverick Scholarship unless they opt out; it cuts estimated tuition and fees from $21,013 to $13,137 (a $7,876 difference). The cost page does not list the renewal requirements.', '16819b4c-6861-5393-b076-99385580b40a');
