insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('90f9a1f6-6c35-50ac-a4d0-0ec62e5f8c12', '2026-27', 'optional', 'Test-optional for freshmen. For international applicants an ACT 20 or SAT 1030 is requested only if the evaluated GPA is below 3.0 or when applying for scholarships. Scholarships needing a minimum score count scores on file by Dec. 1.', '1b14ea30-97b8-53af-9211-293641b0f9c6');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('90f9a1f6-6c35-50ac-a4d0-0ec62e5f8c12', '2026-27', array['common_app','own']::text[], 60, '$60 fee for international students ($50 domestic). Certified, translated transcripts; MSU recommends a NACES-member course-by-course evaluation. Common App opens Aug. 5; MSU''s own application opens Aug. 1.', '1b14ea30-97b8-53af-9211-293641b0f9c6');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('7f0d5eab-387a-5c95-9493-894bcc08ae71', '90f9a1f6-6c35-50ac-a4d0-0ec62e5f8c12', '2026-27', 'application', 'ROLLING', 'Fall 2027 application (rolling)', '2027-08-01', 'The catalog says fall applications should be received by Aug. 1; the freshman page says the application stays open until the 10th day of classes. Students outside the U.S. should apply at least four months before enrollment. Decisions usually take 2-3 weeks once materials are complete.', 'a645402a-0cbe-50d4-8ed0-3e02d43eadaf'),
 ('6fa91d29-2736-59f3-8254-3f4d47d3c1b3', '90f9a1f6-6c35-50ac-a4d0-0ec62e5f8c12', '2026-27', 'scholarship', null, 'Priority date for the General Scholarship Application (incoming freshmen)', '2026-12-01', 'Application opens Oct. 1. The automatic non-resident academic scholarship needs no separate application.', 'b86860fc-b9b5-5806-968d-9129823b267a');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('90f9a1f6-6c35-50ac-a4d0-0ec62e5f8c12', 'required_nonnative', 'Citizens of a list of English-speaking countries are exempt, as are degree-seeking freshmen with two years at and graduation from an accredited U.S. high school with at least a C in English. Intensive English training does not by itself waive the requirement, but students who lack a qualifying score enroll in the English Language Institute (ELI), and completing ELI counts as demonstrating proficiency. Some departments require higher scores.', '1b14ea30-97b8-53af-9211-293641b0f9c6');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select '90f9a1f6-6c35-50ac-a4d0-0ec62e5f8c12'::uuid, 'required_option', '1b14ea30-97b8-53af-9211-293641b0f9c6'::uuid, v.* from (values
 ('TOEFL_IBT', 71, 'The page does not mention the new 1-6 TOEFL scale.'),
 ('IELTS', 6.0, null),
 ('DUOLINGO', 105, 'MSU policy AOP 12.29 (2023) lists 120; the current admissions page says 105.')) v;
