insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, pct_submit_sat, pct_submit_act, notes, source_id, source_note) values
 ('d71f213f-fd70-5e73-9a48-ac93c281257a', '2023-2024', 11901, 10836, 2841, 6, 77, 'IPEDS ADM2023 (fall 2023 first-time students): 11,901 applicants, 10,836 admitted, 2,841 enrolled. College Navigator fall 2024: 11,584 applicants, 91% admitted. IPEDS reports no nonresident-alien applicant counts for Missouri State, so international admit figures are null; nonresidents are about 2% of undergraduates (fall 2024, rounded). Undergraduate enrollment 20,584 (fall 2024) includes many dual-credit high school students; student-faculty ratio 21:1. No readable Common Data Set was found for this college, so this is the IPEDS baseline; GPA, residency and class-rank details are not included.', 'adccbc6a-9089-5fb1-93aa-cdc5d622d594', 'admissions_site');
insert into test_score_percentiles (institution_id, cds_year, source_id, test, p25, p50, p75)
select 'd71f213f-fd70-5e73-9a48-ac93c281257a'::uuid, '2023-2024', 'adccbc6a-9089-5fb1-93aa-cdc5d622d594'::uuid, v.* from (values
 ('SAT_ERW', 490, 560, 620),
 ('SAT_MATH', 500, 550, 600),
 ('ACT_COMPOSITE', 19, 22, 25),
 ('ACT_ENGLISH', 18, 22, 26),
 ('ACT_MATH', 17, 21, 25)) v;
insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('d71f213f-fd70-5e73-9a48-ac93c281257a', '2026-27', 'optional', 'SAT/ACT are not required for international admission (checklist). Domestic first-year applicants with a 3.00+ high school GPA and the required courses are guaranteed admission without scores; below 3.00 a selection index applies (e.g. GPA 2.85-2.99 needs ACT 21 / SAT 1060). International first-year applicants need an academic record equivalent to a 2.5 GPA on a 4.0 scale.', '067c3600-f01b-51d9-b97a-0ff3fdc01f38');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('d71f213f-fd70-5e73-9a48-ac93c281257a', '2026-27', array['own']::text[], 50, 'International applicants use Missouri State''s International Student Application (''own''); the $50 fee must be paid before processing (2.95% card surcharge). Required: official records for classes 9-11 or 10-12 with English translation, TOEFL/IELTS or other accepted test sent directly, statement of financial support and an official bank letter. The domestic application fee is $40 and the Common App is accepted for domestic first-year applicants.', '067c3600-f01b-51d9-b97a-0ff3fdc01f38');
insert into deadlines (id, institution_id, cycle, kind, label, due_date, notes, source_id) values
 ('6610859c-c2bb-5754-a973-bc9c28edb2ea', 'd71f213f-fd70-5e73-9a48-ac93c281257a', '2026-27', 'application', 'Undergraduate application deadline for fall 2027 (international)', '2027-06-01', 'The International Services page lists Fall undergraduate June 1 with no year, treated as fall 2027; the I-20 request deadline is also June 1 and I-20 issuance for fall starts March 1. Domestic first-year applicants hear first-round decisions by Dec. 15, 2026.', 'c2ceb492-2eb9-526b-b166-072cb493471d');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('d71f213f-fd70-5e73-9a48-ac93c281257a', 'required_nonnative', 'Required for applicants in nonimmigrant status whose primary language is not English; the minimum is CEFR B2. Citizens of approved exempt countries are exempt, and applicants with one or more years of full-time secondary or post-secondary study in the U.S. or a country where English is the primary language may be exempt at the discretion of International Services. Students below B2 can complete Missouri State''s English for Academic Purposes (EAP) program, and individual subscores below the stated floors trigger an EAP course in the first semester.', 'fceca28c-8b78-578e-8894-885b33660575');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select 'd71f213f-fd70-5e73-9a48-ac93c281257a'::uuid, 'required_option', 'fceca28c-8b78-578e-8894-885b33660575'::uuid, v.* from (values
 ('TOEFL_IBT', 61, 'Any single band below 15 requires an EAP course in the first semester. The policy document does not give a new 1-6 scale minimum, so no TOEFL_IBT_2026 value is listed.'),
 ('IELTS', 5.5, 'Any subscore below 5.0 requires an EAP course in the first semester.'),
 ('DUOLINGO', 95, 'Subscores below 95 require an EAP course in the first semester.'),
 ('PTE', 44, 'Subscores below 44 require an EAP course in the first semester. Also accepted: Linguaskill 162, iTEP Academic 3.7, GTEC 1180.')) v;
insert into score_codes (institution_id, test_key, code, notes, source_id)
select 'd71f213f-fd70-5e73-9a48-ac93c281257a'::uuid, v.* from (values
 ('sat', '6665', 'Missouri State code for SAT.', '434fe8c6-1cce-5535-b8ae-3db29bf7ce3b'::uuid),
 ('act', '2370', 'Missouri State code for ACT.', '434fe8c6-1cce-5535-b8ae-3db29bf7ce3b'::uuid),
 ('toefl', '6665', 'Missouri State school code for TOEFL/IELTS reports.', '067c3600-f01b-51d9-b97a-0ff3fdc01f38'::uuid),
 ('ielts', null, 'Scores must be sent directly by the testing agency; the checklist gives school code 6665 for TOEFL/IELTS, but IELTS does not use numeric ETS codes.', '067c3600-f01b-51d9-b97a-0ff3fdc01f38'::uuid),
 ('duolingo', null, 'No institution code is listed.', 'fceca28c-8b78-578e-8894-885b33660575'::uuid),
 ('pte', null, 'No institution code is listed.', 'fceca28c-8b78-578e-8894-885b33660575'::uuid)) v;
insert into cost_aid (institution_id, year, tuition_intl_usd, other_usd, total_coa_usd, intl_need_aid, meets_full_need, notes, source_id) values
 ('d71f213f-fd70-5e73-9a48-ac93c281257a', '2026-2027', 23760, 15068, 40519, false, false, 'International Costs page (undated, accessed 2026-10-26; labeled 2026-2027 as the current page): undergraduate tuition and fees $23,760 per year at 15 credit hours per semester, living expenses $15,068 (housing, food and personal, not itemised, in other_usd), health insurance $1,691, total $40,519. Before the 40% I Succeed reduction.; College Navigator 2024-25: tuition and fees in-state $9,502, out-of-state $18,770; on-campus food and housing $11,006, other $3,924; total_coa_usd is the out-of-state on-campus total.; Missouri State publishes a 40% reduction in international tuition (the International Partnership Scholarship) for students who complete the 14-credit ''I Succeed'' first-semester package, which is required for students at CEFR B1 English and optional at B2+; the page says the lower price continues for all classes (about $3,475 saved per semester, exact prices may change). No other international merit scholarship or need-based aid was found, so the aid policy is left unset.', '9c0e8db6-925b-5c39-a203-cd85262187ba');
