insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('75fa337b-1b23-5aaf-b883-8ba802560f40', '2026-27', 'optional', 'Submitting SAT or ACT scores is optional for first-year applicants, including international applicants. Official scores can be sent with CEEB code 002520 (SAT) or ACT code 2572.', 'e71287fd-6b12-5aea-a6ca-67b2e08c9452');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('75fa337b-1b23-5aaf-b883-8ba802560f40', '2026-27', array['common_app','own']::text[], 65, 'Apply with the Montclair State application or the Common App; $65 non-refundable fee (fee waivers are need-based). International first-year applicants submit secondary transcripts (certified English translation), an essay/personal statement (prompts vary by major), and English proficiency scores if not exempt. A recommendation letter from a counselor or teacher is strongly encouraged but not required for most majors (Dance, Musical Theatre and Theatre require two). Nursing needs a nursing-specific essay and extra recommendations; some College of the Arts programs require auditions or portfolios. Admission is rolling.', '4f569d1a-c6a4-5481-931a-21e0fbca7f1f');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notification_date, notes, source_id) values
 ('a514b0ec-c619-5003-b607-7db75d04acf9', '75fa337b-1b23-5aaf-b883-8ba802560f40', '2026-27', 'application', 'EA', 'Early Action, international (fall 2027 entry)', '2026-12-01', '2026-12-24', 'Decisions released by Dec. 24, 2026 (College of the Arts applicants may hear later because of audition/portfolio review). The page encourages early application for scholarship consideration.', '4f569d1a-c6a4-5481-931a-21e0fbca7f1f'),
 ('a83e385e-4e04-5af3-8d48-546741e66b63', '75fa337b-1b23-5aaf-b883-8ba802560f40', '2026-27', 'application', null, 'Nursing application deadline (fall 2027 entry)', '2027-02-01', '2027-04-01', 'Decisions released by Apr. 1, 2027.', '4f569d1a-c6a4-5481-931a-21e0fbca7f1f'),
 ('3e96f7e3-ff01-5821-96c9-2bde8d489557', '75fa337b-1b23-5aaf-b883-8ba802560f40', '2026-27', 'scholarship', null, 'Scholarship consideration deadline (fall 2027 entry)', '2027-03-01', null, null, '4f569d1a-c6a4-5481-931a-21e0fbca7f1f'),
 ('74b7c4ff-eb17-5887-a45a-402527525e85', '75fa337b-1b23-5aaf-b883-8ba802560f40', '2026-27', 'application', 'ROLLING', 'Final international application deadline (fall 2027 entry)', '2027-06-01', null, 'Suggested deadline for students outside the U.S.; students already in the U.S. may have more flexibility. Decisions typically 3-6 weeks after the application is complete. The page''s January-start (spring) line prints ''November 1, 2027'', which is not used here.', '4f569d1a-c6a4-5481-931a-21e0fbca7f1f'),
 ('6f3b57b1-0ecf-593c-95da-1952583fc129', '75fa337b-1b23-5aaf-b883-8ba802560f40', '2026-27', 'other', null, 'I-20 application deadline (fall 2027 entry)', '2027-06-15', null, 'I-20 is issued within 5-10 business days after a complete I-20 application.', '4f569d1a-c6a4-5481-931a-21e0fbca7f1f');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('75fa337b-1b23-5aaf-b883-8ba802560f40', 'required_nonnative', 'Waived for U.S. citizens and for students who graduated from (or attended an international school following the system of) the United States or a listed English-speaking country (e.g. Australia, Canada except Quebec, Ireland, Jamaica, Nigeria, South Africa, United Kingdom). Other accepted proof: iTEP 3.7, SAT EBRW 480+, or ACT English 22+. The page lists no ESL or conditional-admission pathway for first-year applicants.', '4f569d1a-c6a4-5481-931a-21e0fbca7f1f');
