insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, tuition_intl_usd, required_fees_usd, room_board_usd, books_usd, other_usd, total_coa_usd, intl_aid_policy, intl_need_aid, intl_need_aid_awarded, intl_avg_award_usd, meets_full_need, merit_scholarships, merit_separate_app, notes, source_id) values
 ('75fa337b-1b23-5aaf-b883-8ba802560f40', '2026-2027', 16588, 27924, 27924, 1222, 17450, 1330, 3882, 51808, 'merit_only', false, 168, 5077, false, true, false, 'Out-of-state on-campus estimate for 2026-27 (international F-1/J-1 students pay out-of-state tuition): tuition $27,924, fees $1,222, housing $10,838, food $6,612, books $1,330, travel $1,380, miscellaneous $2,430, loan fee $72 (total $51,808). In-state tuition is $16,588.; CDS H6 (2025-26): 168 undergraduate degree-seeking nonresidents received institutional aid, average $5,077 (total $852,895). The CDS box checked is ''need-based'', but the international admissions page says Montclair cannot offer need-based aid to international students (merit and talent awards only).; Montclair cannot offer need-based aid to international students. Qualified first-year international students are automatically awarded the renewable (up to four years) Presidential Scholarship based on GPA criteria; the amount and GPA cutoffs are not published (details are given upon acceptance). Talent-based performing arts awards are also open to international students.', '6eace90d-305f-530d-b4ff-214f9cd7fcec');
