insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, intl_applicants, intl_admits, pct_submit_act, notes, source_id, source_note) values
 ('f45dc484-939f-5784-a6b0-dac075dc8596', '2023-2024', 9889, 8594, 2156, 24, 20, 74, 'IPEDS ADM2023 (fall 2023 first-time students): 9,889 applicants, 8,594 admitted, 2,156 enrolled; international (nonresident alien) first-time applicants 24, admitted 20, enrolled 9, so the international sample is very small. College Navigator fall 2024: 9,246 applicants, 87% admitted. UNO reports ACT only (no SAT percentiles). Undergraduate enrollment 11,756 and 15:1 ratio are fall 2024; nonresidents are about 3% of undergraduates (rounded). No readable Common Data Set was found for this college, so this is the IPEDS baseline; GPA, residency and class-rank details are not included.', '954490e8-92cd-5f47-9a73-0da596593cd1', 'admissions_site');
