insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('9209cf3a-58fd-50ea-9b5e-3c5765f08d24', '2026-27', 'optional', 'First-time freshmen qualify with a secondary-school GPA of 2.75 or an ACT composite of 21 or an SAT of 1060 (or GED 480 / HiSET 45), so scores are an alternative to GPA rather than required. International applicants also need a foreign credential evaluation from a NACES-approved agency.', 'f17493eb-d14c-5acc-b47f-a2fc17442d85');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('9209cf3a-58fd-50ea-9b5e-3c5765f08d24', '2026-27', array['own']::text[], 50, 'International undergraduate applications are processed by International Student and Scholar Services; the $50 fee cannot be waived or deferred. Transcripts, test scores and credential evaluations must come directly from the school, testing agency or evaluation agency (email admissions@nmsu.edu). The process can take up to 3 months.', '74ba6052-1630-58dc-8803-6e76e0f11bfd');
insert into deadlines (id, institution_id, cycle, kind, label, due_date, notes, source_id) values
 ('49b7aae1-46d7-5e77-a460-8d27eda8fbf4', '9209cf3a-58fd-50ea-9b5e-3c5765f08d24', '2026-27', 'application', 'Fall 2027: application must be initiated', '2027-07-01', 'Published as ''July 1 (application initiated)'' with no year, treated as fall 2027. NMSU says it has no university-wide deadline beyond these dates but advises applying 6 months or more ahead.', 'f17493eb-d14c-5acc-b47f-a2fc17442d85'),
 ('5e298c3d-4a53-5605-ad2e-b7ae04daf0f4', '9209cf3a-58fd-50ea-9b5e-3c5765f08d24', '2026-27', 'application', 'Fall 2027: all supporting documents received', '2027-07-15', 'Published as ''July 15 (all documents submitted)'' with no year, treated as fall 2027.', 'f17493eb-d14c-5acc-b47f-a2fc17442d85'),
 ('2a461bb1-52e6-5f9d-9499-4729010acb76', '9209cf3a-58fd-50ea-9b5e-3c5765f08d24', '2026-27', 'scholarship', 'International Competitive Scholarship window closes (fall 2027)', '2027-07-15', 'The application is open May 15 to July 15 for fall (year not printed, treated as 2027) and closes earlier once the available awards are used; it is only open to students with an I-20.', '1497e189-fb6e-50ca-b90a-39b12d0effee');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('9209cf3a-58fd-50ea-9b5e-3c5765f08d24', 'required_nonnative', 'Citizens of the listed English-speaking countries (e.g. UK, Ireland, Canada except Quebec, Australia, New Zealand, Singapore, Philippines, South Africa, Nigeria, Kenya and others) are exempt. Others may be waived after two full years at a U.S. high school or 24 semester credits at a U.S. college with a 2.0 GPA. NMSU may still require any applicant to submit a test. Scores must be less than two years old; institutional TOEFL is not accepted. Admitted international students take NMSU''s English Language Placement Test.', 'f17493eb-d14c-5acc-b47f-a2fc17442d85');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select '9209cf3a-58fd-50ea-9b5e-3c5765f08d24'::uuid, 'required_option', 'f17493eb-d14c-5acc-b47f-a2fc17442d85'::uuid, v.* from (values
 ('TOEFL_IBT_2026', 3.5, 'The admissions page states ''minimum TOEFL of 3.5 iBT'', which is the new 1-6 scale. An old-scale (0-120) admission minimum is not printed on that page.'),
 ('IELTS', 6.0, null),
 ('DUOLINGO', 95, null)) v;
insert into score_codes (institution_id, test_key, code, notes, source_id)
select '9209cf3a-58fd-50ea-9b5e-3c5765f08d24'::uuid, v.* from (values
 ('sat', null, 'NMSU''s pages read do not print a separate SAT code; look it up in the College Board code search.', '74ba6052-1630-58dc-8803-6e76e0f11bfd'::uuid),
 ('act', null, 'No ACT code is printed on the pages read; look it up at act.org.', '74ba6052-1630-58dc-8803-6e76e0f11bfd'::uuid),
 ('toefl', '4531', 'The FAQ gives institution code 4531 for TOEFL, IELTS, GRE and Duolingo results.', '74ba6052-1630-58dc-8803-6e76e0f11bfd'::uuid),
 ('ielts', null, 'The FAQ says to use institution code 4531 for IELTS results; IELTS has no numeric ETS code.', '74ba6052-1630-58dc-8803-6e76e0f11bfd'::uuid),
 ('duolingo', null, 'The FAQ says to use institution code 4531 for Duolingo results.', '74ba6052-1630-58dc-8803-6e76e0f11bfd'::uuid),
 ('pte', null, 'PTE is not listed among NMSU''s accepted undergraduate tests.', 'f17493eb-d14c-5acc-b47f-a2fc17442d85'::uuid)) v;
insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, room_board_usd, books_usd, other_usd, total_coa_usd, intl_aid_policy, intl_need_aid, meets_full_need, merit_scholarships, merit_separate_app, notes, source_id) values
 ('9209cf3a-58fd-50ea-9b5e-3c5765f08d24', '2024-2025', 8183, 25307, 12282, 1250, 4536, 43375, 'merit_only', false, false, true, true, 'College Navigator 2024-25: tuition and fees in-state $8,183, out-of-state $25,307; on-campus food and housing $12,282, other $4,536; total_coa_usd is the out-of-state on-campus total. NMSU''s International Competitive Scholarship can reduce an international student''s tuition to the in-state rate (see aid notes).; International Competitive Scholarship: a tuition discount (in-state instead of out-of-state tuition) plus a $100 cash stipend each fall and spring, for new degree-seeking F-1 students with an I-20, renewable up to 8 semesters. Freshman eligibility e.g. GPA 3.50 with TOEFL 68 / IELTS 6.0 / Duolingo 95, or GPA 3.25 with TOEFL 79 / IELTS 6.5 / Duolingo 100, or GPA 3.50 for students from English-exempt countries. Awards are limited and competitive and the separate application closes when awards run out. (TOEFL values here are the scholarship tiers, not the admission minimum.)', '873f9753-a780-5869-a30f-abd11ad2db24');
