insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('367be2ae-a805-58bb-9ea2-631bb3f88e3e', '2026-27', 'optional', 'SAT/ACT are not required for admission; CDS C8F: scores are optional, used case by case to enhance the academic profile, and not required for scholarship consideration.', '814332b2-2d55-5528-aa79-25d421612cce');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('367be2ae-a805-58bb-9ea2-631bb3f88e3e', '2026-27', array['own']::text[], 50, 'International applicants use NAU''s international application: $50 undergraduate fee (the domestic fee is $40), official transcripts (certified translation if not in English), passport copy, English proficiency and proof of financial support for the I-20. Minimum 2.5 GPA for the last 3 years of secondary school. The enrollment fee for first-year undergraduates is $325. No essay or recommendation is listed.', 'd79fa5ad-406f-53c0-8b93-b5468abeadd9');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('8e7cb2dc-15be-542f-a086-6c11b9f41fe0', '367be2ae-a805-58bb-9ea2-631bb3f88e3e', '2026-27', 'priority', null, 'Priority admission, fall 2027 (international)', '2027-03-01', 'NAU accepts international undergraduate applications year-round; applying by the priority date gives an earlier decision, access to the housing application and more time for the I-20 and visa. Spring priority is Sept. 15. NAU recommends applying 4-6 months before the start date.', 'eeaa8dbe-5375-5ac6-b43a-beed04c7adfc'),
 ('e9c115a4-f800-546a-a0ac-ef4cbd115753', '367be2ae-a805-58bb-9ea2-631bb3f88e3e', '2026-27', 'application', 'ROLLING', 'Application closing date, fall (CDS)', '2027-08-01', 'CDS C14 gives Aug. 1 (no year printed) and C16 says decisions are sent on a rolling basis. The international pages publish no hard deadline other than the priority dates.', '814332b2-2d55-5528-aa79-25d421612cce');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('367be2ae-a805-58bb-9ea2-631bb3f88e3e', 'required_nonnative', 'Other accepted proof: ACT English and Reading 21+, SAT EBRW 350+, IB English A (5 HL / 6 SL) or English B (7), transfer of one 3-credit English composition course, four years of English at a high school taught entirely in English (with school verification), exchange students with B2 English; citizens of English-speaking countries need no proof. Applicants below the minimum may enroll in the Program in Intensive English (PIE), with entry scores of Duolingo 55, IELTS 4 or TOEFL 20, until they meet NAU''s requirement.', 'd79fa5ad-406f-53c0-8b93-b5468abeadd9');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
