insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('a2aec953-f2a7-5d9e-bb7b-e0a27429d1cc', '2026-27', 'optional', 'Students can apply without consideration of a test score and be admitted on a full review of the high school transcript. International ''assured admission'' is stated as high school GPA 3.0+ (4.0 scale, recalculated by OSU) plus the English requirement; no SAT/ACT is listed. Scores raise scholarship awards (ACT/SAT/IELTS/TOEFL/Duolingo/PTE grid).', '0c63d693-189d-5f74-9f29-0475b6e27f55');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('a2aec953-f2a7-5d9e-bb7b-e0a27429d1cc', '2026-27', array['common_app','own']::text[], 90, 'International application fee is $90 (domestic $50). OSU application opens July 1; Common App opens Aug. 1; submit only one. The application is also the scholarship application. Required uploads: passport ID page, English test, transcripts (OSU does not accept third-party credential evaluations), financial guarantee form plus bank letter. A leadership and involvement resume is needed for full scholarship consideration.', '14838f63-daf5-5728-a9fb-8bb7fc0ed0d8');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('25d92914-332d-570d-8ba8-e88a0f354607', 'a2aec953-f2a7-5d9e-bb7b-e0a27429d1cc', '2026-27', 'application', 'ROLLING', 'International fall application deadline (applicants not living in the U.S.)', '2027-06-01', 'Applicants currently living in the U.S. have July 1. The page lists ''Fall: June 1'' without printing a year; taken as the fall 2027 cycle. Spring is Nov. 1 (Dec. 1 if living in the U.S.).', 'c6be94d0-7083-5c0f-912d-1ae02554b9ad'),
 ('fa7b3d1f-bbd3-5c47-8afb-e0be556d7215', 'a2aec953-f2a7-5d9e-bb7b-e0a27429d1cc', '2026-27', 'scholarship', null, 'Early Opportunity Scholarship deadline (freshmen)', '2026-11-01', 'Complete application incl. leadership and involvement resume, and submit test scores, for maximum scholarship consideration.', 'c6be94d0-7083-5c0f-912d-1ae02554b9ad'),
 ('080991eb-b8b1-52dd-bd6b-e0106d97a1a2', 'a2aec953-f2a7-5d9e-bb7b-e0a27429d1cc', '2026-27', 'scholarship', null, 'Priority scholarship deadline (freshmen)', '2027-02-01', 'Full scholarship consideration requires all materials by this date; later applications are considered only if funds remain. Absolute scholarship deadline is Aug. 13.', 'ffd65b85-ee76-52ae-8a33-ae3172df7cff'),
 ('fb552b7f-c95b-526d-88e0-204d5e42cb6d', 'a2aec953-f2a7-5d9e-bb7b-e0a27429d1cc', '2026-27', 'deposit', null, 'College Decision Date (enrollment deposit $300, $250 refundable until May 1)', '2027-05-01', 'Enrollment deposit opens Dec. 1; some scholarships must be accepted by May 1.', 'c6be94d0-7083-5c0f-912d-1ae02554b9ad');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('a2aec953-f2a7-5d9e-bb7b-e0a27429d1cc', 'required_nonnative', 'Waived for graduates of an accredited high school where English is the primary language of instruction in a country where English is the primary language, and for students who attended English-speaking U.S. high schools for 2+ years. TOEFL/IELTS scores are valid two years. Conditional admission is offered to students who meet everything except English (see notes on the English rows).', '14838f63-daf5-5728-a9fb-8bb7fc0ed0d8');
