select 'a2aec953-f2a7-5d9e-bb7b-e0a27429d1cc'::uuid, 'required_option', v.* from (values
 ('TOEFL_IBT_2026', 3.5, 'Page gives ''iBT TOEFL Internet-Based Score 3.5+'' (the 1-6 scale) and does not list an old 0-120 minimum. Conditional admission minimum 3.0. TOEFL send code 6546. Institutional-test TOEFL not accepted.', '14838f63-daf5-5728-a9fb-8bb7fc0ed0d8'::uuid),
 ('IELTS', 5.5, 'IELTS Academic. Conditional admission minimum 5.0.', '14838f63-daf5-5728-a9fb-8bb7fc0ed0d8'::uuid),
 ('DUOLINGO', 95, 'Accepted from fall 2024. Conditional admission minimum 85.', '766dc2dc-2304-51b0-8e87-3ebfec003a7b'::uuid),
 ('PTE', 46, 'PTE Academic. Conditional admission minimum 36. iTEP Academic 3.5 (conditional 3.0) is also accepted but is not a listed test here.', '14838f63-daf5-5728-a9fb-8bb7fc0ed0d8'::uuid)) v;
