insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('6a37a137-19e5-5455-a2ce-8901f5b5b815', '2026-27', 'optional', 'SAT/ACT/CLT are optional for all applicants, including international. Scores are required to be considered for the Regents Scholars Program merit scholarships. SAT or ACT is required for home-schooled applicants.', '08d25be1-d735-56ac-8ac6-51d54c0f0edc');
insert into application_requirements (institution_id, cycle, platforms, supplemental_essays, teacher_recs, interview, app_fee_usd, fee_waiver, notes, source_id) values
 ('6a37a137-19e5-5455-a2ce-8901f5b5b815', '2026-27', array['common_app']::text[], 'Common App personal essay plus one Pepperdine essay (300-500 words) on why you are interested in a Christian university and how you would contribute to conversations of faith on campus.', 1, 'optional_evaluative', 70, true, 'One academic letter of recommendation from a core-subject teacher or counselor (the page says teacher or counselor). Sixth-semester (through grade 11) transcript required at application. Fee waiver for financial need per CDS C13. Nursing applicants must apply Regular Decision (deadlines page).', '12a0e172-27d7-5db8-a18c-4de74996aa9f');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notification_date, notes, source_id) values
