insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('6a37a137-19e5-5455-a2ce-8901f5b5b815', 'required_nonnative', 'International first-years must show English proficiency by one of: SAT EBRW 600+, ACT Reading 24+, TOEFL iBT 85+, Cambridge C1/C2 186+, Duolingo 120+, LanguageCert Academic 70+, IELTS 6.5+, a B or better in a US college English Composition course, C or better in A-Level/AS English, IB English 5+, or 4 years at a high school taught in English (verified by a counselor). Scores must be within 2 years of application. TOEFL MyBest scores not accepted.', '93fd1f97-c2ee-52f9-a965-ab88b573b1a4');
