insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('2ea3c1e4-e561-5ad8-b07e-c39055855d32', '2026-27', 'optional', 'Test-optional extended through fall 2028 entry (covers fall 2027), including international applicants. Pitt takes the highest ACT composite and highest SAT superscore; SAT Essay / ACT Writing not required.', '2b82dd5f-dad4-5cb2-b8b0-d658cf7254df');
insert into application_requirements (institution_id, cycle, platforms, interview, app_fee_usd, notes, source_id) values
 ('2ea3c1e4-e561-5ad8-b07e-c39055855d32', '2026-27', array['common_app','own']::text[], 'not_offered', 55, 'Common App or the Pitt Application are equally acceptable. International applicants must submit a personal statement or the Common App essay. No admissions interviews, but international applicants may submit an InitialView interview. Fee of $55 is from the first-year page; the international page does not state a separate amount. Rolling admission; Frederick Honors College and Guaranteed Admission Programs have their own earlier dates.', '853c40bc-ea87-5a32-bad2-4bd9044b5ad4');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('8061749f-d640-5fe3-8d42-88c9635a2769', '2ea3c1e4-e561-5ad8-b07e-c39055855d32', '2026-27', 'application', 'ROLLING', 'Fall term, international first-year (complete application)', '2027-04-01', 'Rolling admission; apply early (application opens Aug 1; decisions about 6-8 weeks after the checklist is complete). The page says the Fall 2027 application is open; the year is implied, not printed next to the date.', '853c40bc-ea87-5a32-bad2-4bd9044b5ad4'),
 ('18c66e16-7163-59ef-8a40-17789ac3d70d', '2ea3c1e4-e561-5ad8-b07e-c39055855d32', '2026-27', 'scholarship', 'ROLLING', 'International first-year merit scholarship review', '2027-02-01', 'Completed application by Feb 1 is automatically reviewed for international merit scholarships. The general first-year page cites Dec 1 for automatic academic scholarship consideration.', '0086d081-0a27-5d44-b56f-f6b750ee6bb0');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('2ea3c1e4-e561-5ad8-b07e-c39055855d32', 'required_nonnative', 'International students are typically required to submit TOEFL, IELTS or Duolingo; waivers are case by case and not automatic (requires contacting Pitt). Waiver profile listed: TOEFL 100+ (subscores 20+; new scale 5.0+ with subscores 4.0+), IELTS 7.0+ (subscores 6.0+), Duolingo 125+, or attended a US high school four years / exempt-country schooling. Only a single-sitting TOEFL iBT is accepted (no MyBest, no Essentials).', '9b0f956d-d22f-5ed9-a754-fdd64c60a676');
insert into english_requirements (institution_id, status, source_id, test_key, recommended_total, notes)
select '2ea3c1e4-e561-5ad8-b07e-c39055855d32'::uuid, 'required_option', '9b0f956d-d22f-5ed9-a754-fdd64c60a676'::uuid, v.* from (values
 ('TOEFL_IBT', 90, 'No hard minimum published. 90-99 with a solid record gets strong consideration for the Pittsburgh campus; 80-89 most often considered for a regional campus (Bradford, Greensburg, Johnstown).'),
 ('TOEFL_IBT_2026', 4.5, 'Page equates 90-99 with 4.5 on the new scale; no hard minimum published.'),
 ('IELTS', null, 'No Pittsburgh-campus minimum published. IELTS 6.5 is listed alongside TOEFL 80-89 (regional-campus range). IELTS Indicator accepted.'),
 ('DUOLINGO', null, 'No Pittsburgh-campus minimum published. 115-120 is listed alongside TOEFL 80-89 (regional-campus range).')) v;
