 ('TOEFL_IBT', 71, '{"reading": 15, "writing": 15}'::jsonb, 'Tests taken before Jan 21, 2026.'),
 ('TOEFL_IBT_2026', 4.0, '{"reading": 3.5, "writing": 3.5}'::jsonb, 'Tests taken on or after Jan 21, 2026 (1-6 scale).'),
 ('IELTS', 6.0, '{"reading": 6.0, "writing": 6.0}'::jsonb, 'Academic IELTS; One Skill Retake scores not accepted.'),
 ('DUOLINGO', 110, null, null),
 ('PTE', 53, null, 'Academic PTE.')) v;
