insert into cost_aid (institution_id, year, tuition_usd, tuition_out_of_state_usd, tuition_intl_usd, required_fees_usd, room_board_usd, books_usd, other_usd, total_coa_usd, intl_aid_policy, intl_need_aid, meets_full_need, merit_scholarships, notes, source_id) values
 ('acbf81e7-aae6-5e60-b80a-26230d495f5e', '2026-2027', 13593, 36249, 25632, 5775, 17445, 750, 2211, 51813, 'merit_only', false, false, true, 'International figures are PSU''s 2026-27 estimate for a 9-month year at 12 credits a quarter: tuition $25,632 ($712 a credit base rate; engineering and business pay up to $782.60), fees plus mandatory health insurance $5,775 (insurance is $1,189 a quarter), housing and meals $17,445, books $750, transportation $828 plus personal $1,383. The $13,593 resident and $36,249 nonresident amounts are PSU''s all-in tuition and fees estimate at about 16 credits a term and are on a different basis.; All admitted undergraduate international students are automatically considered for merit scholarships of up to $10,000 per year. The International Achievement Scholarship pays $3,000 to $10,000 a year for up to 12 terms for first-years (typical entering GPA 3.25+; no separate application). The University Honors Laurels Scholarship adds up to $3,000 a year for students admitted to the Honors College. Awards apply to tuition and require 12 credits a quarter.', '58a2384e-4519-5b4b-b57f-047974ec1721');
