insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('7d143b07-c6d4-5ab5-aa68-8a12e1b0fea0', 'required_nonnative', 'Applicants whose first language is not English must either complete at least two years of full-time study in an English-language curriculum before applying or submit an official score meeting the minimums. TOEFL iBT Home Edition accepted.', '858965fb-b926-5bfe-8bd8-f84a676bb61d');
