insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, intl_applicants, intl_admits, in_state_applicants, in_state_admits, out_state_applicants, out_state_admits, pct_submit_sat, pct_submit_act, gpa_avg, pct_reporting_gpa, gpa_distribution, notes, source_id) values
 ('d32b990a-4357-5a99-81ab-626a5c04dcbe', '2025-2026', 37124, 29845, 4943, 810, 638, 34882, 28137, 1432, 1070, 9, 1, 3.5, 99.41, '{"4.0": 17.1, "3.75-3.99": 17.6, "3.50-3.74": 20.0, "3.25-3.49": 18.6, "3.00-3.24": 13.4, "2.50-2.99": 12.8, "2.0-2.49": 0.5, "1.0-1.99": 0.0}'::jsonb, 'CDS C1 fall 2025 first-year class. Residency split is by physical address at application (C1). No early decision or early action; no waitlist. All majors are ''impacted'' (more eligible applicants than space), so meeting CSU minimums does not guarantee admission. SJSU is test-blind: only 9% (SAT) and 1% (ACT) of enrolled students had scores, so the score ranges below describe that small self-selected group.', '487fe752-9351-569c-a435-0b9909c9db55');
