insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, pct_submit_sat, pct_submit_act, notes, source_id, source_note) values
 ('e4ff3ae7-8bc6-5099-bfc3-cef5bc8b0fb5', '2024-2025', 15956, 13241, 3496, 16, 12, 'Baseline from IPEDS fall 2024 (College Navigator percentages; exact counts from the NCES IPEDS ADM2024 file via the Urban Institute Education Data Portal). SCAD does not publish a Common Data Set on the pages reviewed, so GPA, international applicants/admits and factors are not recorded. The 2,207 international undergraduates are IPEDS fall 2024 nonresident aliens (about 14% of 15,552). Percentiles come only from the 16% (SAT) and 12% (ACT) of enrolled students who submitted scores; SCAD is test-optional.', '95c347d1-5fbe-53aa-928a-6963cf453288', 'admissions_site');
