 ('act', '1759', 'Page prints ''ACT/SAT: Institution code 1759''.', '6c0e06ad-7938-593d-94b2-d58fc8895b04'::uuid),
 ('toefl', '1759', 'The English proficiency page prints the institutional code as 001759.', '38a9188d-b076-5199-ab63-35d9339be6a6'::uuid),
 ('ielts', null, 'No institution code is listed; official reports go directly from the testing service to SIUE.', '38a9188d-b076-5199-ab63-35d9339be6a6'::uuid),
 ('duolingo', null, 'No institution code is listed.', '38a9188d-b076-5199-ab63-35d9339be6a6'::uuid),
