insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('43709a15-6b1f-50c7-b209-bec4c4ba2c1b', '2026-27', 'optional', 'The international admissions page lists ''Official SAT or ACT score (optional, but highly encouraged)''. Domestic criteria are any one of: ACT 18 (or SAT 970), Smarter Balanced Level 3+, 2.6 HS GPA, or top 60% of class.', 'd0c91b3a-6f53-5eba-8a13-a3302fd433fd');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('43709a15-6b1f-50c7-b209-bec4c4ba2c1b', '2026-27', array['own']::text[], 25, 'Apply through the South Dakota Board of Regents application (apply.sdbor.edu); $25 fee. The international page states no minimum GPA and says applicants are evaluated on academic preparation, prior performance and English proficiency. International students are not eligible for conditional admission. Essay and recommendation requirements are not stated.', 'd0c91b3a-6f53-5eba-8a13-a3302fd433fd');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('8c840587-11d0-5e94-badc-e50a74873ed8', '43709a15-6b1f-50c7-b209-bec4c4ba2c1b', '2026-27', 'application', 'RD', 'International application deadline, fall 2027', '2027-03-01', 'Page prints ''Fall semester: March 1'' (spring: Oct. 1) without a year; treated as fall 2027. Domestic admission is rolling.', 'd0c91b3a-6f53-5eba-8a13-a3302fd433fd');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('43709a15-6b1f-50c7-b209-bec4c4ba2c1b', 'required_nonnative', 'Waived with a college-level English composition course (C or higher) at an accredited U.S. institution, graduation from a U.S. regionally accredited high school, or citizenship of listed countries (e.g., Ireland, Jamaica, New Zealand, Singapore, South Africa, UK; Nigeria and Liberia need WAEC English B3+). Also accepted: SAT Reading/Writing 490, ACT composite 18, IGCSE O-level English B, IB English A HL 5. Scores must be from the last 2 years. International students are not eligible for conditional admission.', '02a5b0b1-733c-57f7-9b31-1a972963dc3e');
