 ('TOEFL_IBT_2026', 'required_option', 3.5, 'The international admissions page lists TOEFL 3.5 without naming the scale; read here as the new 1-6 scale.', 'd0c91b3a-6f53-5eba-8a13-a3302fd433fd'::uuid),
 ('IELTS', 'required_option', 5.5, 'IELTS Academic, overall band.', '02a5b0b1-733c-57f7-9b31-1a972963dc3e'::uuid),
 ('DUOLINGO', 'required_option', 90, null, '02a5b0b1-733c-57f7-9b31-1a972963dc3e'::uuid),
