insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('e7afddbc-ddc1-5066-ad00-770337d69f80', '2026-27', 'optional', 'International applicants with an equivalent U.S. GPA of 2.6+ out of 4.0, OR ACT 21+, OR SAT 1070+ will generally be admitted, so scores are one of three alternative routes rather than a requirement. Official ACT/SAT scores are sent before I-20 issuance ''if applicable''.', 'f48a2395-b8d7-5259-8b13-4f05aba55440');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('e7afddbc-ddc1-5066-ad00-770337d69f80', '2026-27', array['common_app','own']::text[], 20, 'The international page says the fee is non-refundable and paid at the end of the online application but does not state the amount; $20 is the fee reported in the CDS (C13) and College Navigator for 2024-25. The CDS lists a Common App page for USD; the international page describes USD''s online application. Immunization form (2 MMR) and Academic Health Plans health insurance are required before arrival. Contingent admission is possible with unofficial or partial transcripts (official transcripts due 30 days before classes).', 'f48a2395-b8d7-5259-8b13-4f05aba55440');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('e63316ed-6198-52b9-ad03-0d81fa27a7ee', 'e7afddbc-ddc1-5066-ad00-770337d69f80', '2026-27', 'scholarship', null, 'International scholarship consideration (fall)', '2027-06-01', 'USD international cost page: June 1 for fall (Oct. 1 for spring) for full consideration of the Coyote Beginnings awards; no separate application.', 'f48a2395-b8d7-5259-8b13-4f05aba55440'),
 ('3de6c05e-4047-5ceb-8a47-e823ddf280a2', 'e7afddbc-ddc1-5066-ad00-770337d69f80', '2026-27', 'application', 'ROLLING', 'International application deadline, fall 2027', '2027-08-01', 'Page lists ''Fall 2027: application deadline August 1'' (spring: Dec. 15). No priority date is published. The enrollment deposit and housing are due July 1 for fall.', 'f48a2395-b8d7-5259-8b13-4f05aba55440');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('e7afddbc-ddc1-5066-ad00-770337d69f80', 'required_nonnative', 'Exempt: a conferred degree from listed English-speaking countries (e.g., Canada, Ireland, Singapore, UK); a U.S. high school or accredited English-medium school; British O Level/GCSE/IGCSE, A Levels or IB (equivalent to 2.6+ GPA); AP English 3+; ELS level 112; or a college English composition course with C or higher at an accredited U.S. institution. Scores must be within 2 years.', 'f48a2395-b8d7-5259-8b13-4f05aba55440');
