insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('d09f2e3a-9467-5f06-b23a-7c98285f9359', '2026-27', 'optional', 'International freshman checklist: SAT or ACT is optional (required only for Freshman Merit Scholarship consideration). USM''s CDS adds that students with a 3.2+ cumulative GPA and the college-preparatory curriculum do not need ACT/SAT, and that Accuplacer can replace SAT/ACT. SAT verbal 480 or ACT English 20 also counts as proof of English.', '01a5d723-b6d8-54cb-82e8-0c8336ad8b50');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('d09f2e3a-9467-5f06-b23a-7c98285f9359', '2026-27', array['own','common_app']::text[], 45, 'USM application or Common Application, $45 non-refundable fee, high school transcripts and/or school-leaving exam results, and proof of English proficiency. Strong freshman applicants present a 2.5 minimum GPA in core academic subjects, evaluated against the applicant''s home education system; applicants must be 17 by the first day of classes. Financial documents are needed for the I-20.', '01a5d723-b6d8-54cb-82e8-0c8336ad8b50');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('1bc89445-93a3-5a5d-8807-3ee3a90f872b', 'd09f2e3a-9467-5f06-b23a-7c98285f9359', '2026-27', 'application', 'ROLLING', 'International application deadline (fall 2027 entry)', '2027-05-01', 'The page prints ''Fall admission (August start date) - May 1'' and ''Spring admission (January start date) - October 1'' without a year; fall is treated as May 1, 2027. Applications must reach International Student and Scholar Services by the deadline. The domestic freshman priority deadline for fall 2027 is listed as August 2027.', '01a5d723-b6d8-54cb-82e8-0c8336ad8b50');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('d09f2e3a-9467-5f06-b23a-7c98285f9359', 'required_nonnative', 'Not required of applicants from the United Kingdom, Australia, English-speaking Canadian provinces, New Zealand, Ireland and English-speaking Caribbean islands (freshmen from African countries must still submit proof). Also met by IB, Cambridge IGCSE/A-Level or a US/Canadian-curriculum school abroad with C or better in all English courses (final three years), three final years at a US/UK/Canada/Australia/NZ secondary school with C or better in English, or C or better in English Composition I and II at an accredited US college. Other accepted tests: SAT verbal 480 / ACT English 20, iTEP Academic 4.0, Oxford ELLT 7, Kaplan 450, Gateway 375.', '01a5d723-b6d8-54cb-82e8-0c8336ad8b50');
insert into english_requirements (institution_id, source_id, test_key, status, min_total, notes)
select 'd09f2e3a-9467-5f06-b23a-7c98285f9359'::uuid, '01a5d723-b6d8-54cb-82e8-0c8336ad8b50'::uuid, v.* from (values
 ('TOEFL_IBT', 'required_option', 71, null),
 ('TOEFL_IBT_2026', 'required_option', 4, 'The page prints ''score of 4 (new)/71 (old)'' and does not name the 1-6 scale.'),
 ('IELTS', 'required_option', 6.0, 'Academic, overall.'),
 ('DUOLINGO', 'required_option', 110, null),
 ('PTE', 'required_option', 54, 'PTE Academic or PTE Express overall.'),
 ('CAMBRIDGE', 'accepted', null, 'B2 First, C1 Advanced or C2 Proficiency; no minimum score is printed.')) v;
