insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('2e083b83-f0ff-575f-8101-e7547bf6ac25', '2026-27', 'optional', '"SAT/ACT scores will not be required for students applying for Fall 2026, Spring 2027, Fall 2027 or Spring 2028 admission." Students who do not submit scores are not disadvantaged and remain eligible for merit scholarships.', '1fd4a151-5a53-5f07-badb-0bfdc73b0b05');
insert into application_requirements (institution_id, cycle, platforms, teacher_recs, counselor_rec, notes, source_id) values
 ('2e083b83-f0ff-575f-8101-e7547bf6ac25', '2026-27', array['common_app','coalition']::text[], 1, true, 'Official high school transcript, senior-year grade report, high school counselor evaluation, and one academic recommendation; ED agreement if applying ED. Some programs add portfolio, audition or other requirements (e.g. School of Architecture and the College of Visual and Performing Arts require a portfolio or audition). Interviews are optional for international applicants (virtual interview or Vericant) and not required for admission. Application fee is not stated on the pages reviewed, so it is left blank. Fee waivers are available (SAT/ACT or NACAC waiver, or counselor request).', '1fd4a151-5a53-5f07-badb-0bfdc73b0b05');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('bee4826c-9c4c-52af-b87d-e9e46cabbe86', '2e083b83-f0ff-575f-8101-e7547bf6ac25', '2026-27', 'application', 'EA', 'Early Action', '2026-11-01', 'First-year only. Notification "Early February" (no fixed date published); reply date May 1.', 'fe9c365e-a2a6-559b-8d0a-bf4494f91363'),
 ('61b01a68-2dc2-5f08-9b04-a52929d6d2bc', '2e083b83-f0ff-575f-8101-e7547bf6ac25', '2026-27', 'application', 'ED', 'Early Decision', '2026-11-01', 'First-year only, binding. Notification "Late December" (no fixed date published); reply by February 15 if admitted to first choice.', 'fe9c365e-a2a6-559b-8d0a-bf4494f91363'),
 ('d15c34ba-5c93-5048-a5aa-87ea06faaea0', '2e083b83-f0ff-575f-8101-e7547bf6ac25', '2026-27', 'application', 'ED2', 'Early Decision II', '2027-01-05', 'First-year only, binding. Notification "Mid-January" (no fixed date published); reply by March 1 if admitted to first choice.', 'fe9c365e-a2a6-559b-8d0a-bf4494f91363'),
 ('420c2042-8b37-56fd-bb4d-6b811b434023', '2e083b83-f0ff-575f-8101-e7547bf6ac25', '2026-27', 'application', 'RD', 'Regular Decision', '2027-01-05', 'Notification begins mid-March and continues weekly through spring; reply date May 1. Some programs (e.g. Drama acting/musical theater prescreen Dec 1; portfolio programs) have earlier or separate dates. The page states no entry year; treated as the 2026-27 cycle (Fall 2027 entry).', 'fe9c365e-a2a6-559b-8d0a-bf4494f91363');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('2e083b83-f0ff-575f-8101-e7547bf6ac25', 'required_nonnative', 'International students studying in the U.S. and non-native speakers must submit an English proficiency exam; waivers are at the Admissions Committee''s discretion and are not guaranteed (e.g. first-year students who attended and graduated from in-person U.S.-based secondary schools for a set period with a qualifying GPA; students in a bilingual or non-English curriculum must still submit proof). The score table also lists SAT-EBRW 600 and ACT-English 27 per college. Not accepted: TOEFL Essentials, ITP, TOEFL MyBest Score, IELTS Indicator. Scores must be sent directly by the testing service.', '40225b52-a043-5d13-9117-ace77f71ede0');
insert into english_requirements (institution_id, source_id, test_key, status, recommended_total, notes)
select '2e083b83-f0ff-575f-8101-e7547bf6ac25'::uuid, '40225b52-a043-5d13-9117-ace77f71ede0'::uuid, v.* from (values
 ('TOEFL_IBT', 'required_option', 85, '"Preferred" score, not a stated hard minimum. 85+ for Arts and Sciences, Maxwell, VPA, Education, Engineering and Computer Science, Falk, iSchool; 90+ for Whitman and Architecture; 102+ for Newhouse. TOEFL At Home accepted.'),
 ('TOEFL_IBT_2026', 'required_option', 4.5, 'Preferred score for tests from 1/21/26: 4.5 (most colleges), 5 for Whitman, Architecture and Newhouse.'),
 ('IELTS', 'required_option', 6.5, 'Preferred 6.5+ (most colleges); 7.0+ for Whitman, Architecture and Newhouse.'),
 ('DUOLINGO', 'required_option', 125, 'Preferred 125+ (most colleges, Whitman, Architecture); 130+ for Newhouse.'),
 ('PTE', 'accepted', null, 'PTE Academic is accepted; the page lists no PTE score in the preferred-score table.'),
 ('CAMBRIDGE', 'accepted', 176, 'Preferred 176+ (most colleges); 185+ for Whitman, Architecture and Newhouse.')) v;
