 ('TOEFL_IBT', 'required_option', 78, '{"each_section": 19, "writing": 18}'::jsonb, 'Each section 19 except Writing 18.'),
 ('TOEFL_IBT_2026', 'required_option', 4, '{"each_section": 4}'::jsonb, 'Updated 6-point scale: total 4, each section 4.'),
 ('IELTS', 'required_option', 6.5, '{"each_section": 6.0}'::jsonb, null),
 ('DUOLINGO', 'required_option', 105, null, 'Some online-program pages list 110.'),
 ('PTE', 'required_option', 52, null, 'PTE Academic overall.'),
 ('CAMBRIDGE', 'accepted', 176, null, 'B2 First, C1 Advanced or C2 Proficiency. Also accepted: TOEFL Essentials 8.5 and iTEP 3.8. No ESL or conditional-admission pathway was found on the international admissions page.')) v;
