 ('toefl', '3901', null, '1ca2c2d3-67d5-5a89-918f-d5cbcd69a13f'::uuid),
 ('ielts', null, 'No IELTS code exists; ask the test center to send scores to the Office of Undergraduate Admissions or have your counselor email a verified copy to undergraduate.admissions@tufts.edu.', '1ca2c2d3-67d5-5a89-918f-d5cbcd69a13f'::uuid),
 ('duolingo', null, 'No code; request that Duolingo release the score to Tufts (no additional fee).', '1ca2c2d3-67d5-5a89-918f-d5cbcd69a13f'::uuid)) v;
insert into cost_aid (institution_id, year, tuition_usd, room_board_usd, books_usd, other_usd, total_coa_usd, intl_aid_policy, intl_need_aid, meets_full_need, merit_scholarships, notes, source_id) values
 ('d5e1a4ce-6a1b-5c22-b3bb-c2404137110a', '2023-2024', 73616, 19566, 1000, 1846, 92054, 'need_aware_full_need', true, true, false, 'College Scorecard (IPEDS 2023-24): tuition includes required fees; on-campus cost of attendance.; Tufts meets 100% of demonstrated need for all admitted students regardless of citizenship, but only ''a limited amount of funding'' is available to international students and aid must be requested at the time of application (not available if requested after admission). No merit-based scholarships for undergraduates. ED applicants can request aid; the package is identical to Regular Decision. The page does not use the words need-blind or need-aware.', 'e057a760-6fdb-569f-b2ff-11a4e0994e3a');
