insert into application_requirements (institution_id, cycle, platforms, supplemental_essays, teacher_recs, counselor_rec, app_fee_usd, fee_waiver, notes, source_id) values
 ('b4cdb308-dd00-576a-bef2-fff2e9ad73f7', '2026-27', array['common_app','coalition']::text[], true, 2, true, 90, true, 'No application fee for students applying for need-based aid; otherwise $90. Supplement = one extended essay plus one short ''why UChicago'' essay. Two recommendations from academic-subject teachers plus the Secondary School Report. International aid applicants should not submit the CSS Profile or FAFSA (UChicago has its own aid process via the UChicago Account).', 'd78229ee-765f-5150-b3f9-30180e8f1872');
