insert into cost_aid (institution_id, year, tuition_usd, room_board_usd, books_usd, other_usd, total_coa_usd, intl_need_aid, meets_full_need, merit_scholarships, merit_separate_app, notes, source_id) values
 ('b4cdb308-dd00-576a-bef2-fff2e9ad73f7', '2023-2024', 73962, 20835, 1800, 2400, 94971, true, true, true, false, 'College Scorecard (IPEDS 2023-24): tuition includes required fees; on-campus cost of attendance.; Committed to meeting 100% of demonstrated need with a loan-free package for admitted applicants who applied for aid. International students are eligible for merit scholarships (partial-tuition) and are considered automatically; no separate application. The page does not state whether international admission is need-blind or need-aware.', 'edc4d124-7a0f-5aa4-b1f0-1d27a0500490');
