insert into application_requirements (institution_id, cycle, platforms, supplemental_essays, teacher_recs, counselor_rec, interview, app_fee_usd, notes, source_id) values
 ('ba6f6326-df17-5b28-9055-e105ba1840ee', '2026-27', array['uc_app']::text[], '4 Personal Insight Questions (choose 4 of 8)', 0, false, 'not_offered', 80, 'Fee is $80 per campus, $95 for international applicants; fee waivers cover up to four campuses but only for U.S. citizens, permanent residents and AB540-eligible applicants. UCLA does not require or accept letters of recommendation and does not offer admission interviews. Some arts, music, nursing and theater/film majors require a supplemental application.', 'aa8ab530-73d8-55f6-8e78-f509db6d9e06');
