insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('cf3d6113-a1d5-5598-a2b8-d012c7ba0c06', '2026-27', 'required', 'All first-year students must submit an SAT, ACT or CLT score (Florida Board of Governors regulation 6.002). UF has no test preference; scores may be self-reported at application, official scores due May 1. UF superscores SAT/ACT (ACT Science excluded).', 'ae21703e-f2e2-51f6-8f0a-99f6867b295a');
insert into application_requirements (institution_id, cycle, platforms, supplemental_essays, app_fee_usd, fee_waiver, notes, source_id) values
 ('cf3d6113-a1d5-5598-a2b8-d012c7ba0c06', '2026-27', array['common_app']::text[], 'Common App personal essay plus the UF Supplement (a few short-answer questions); Honors Program and Innovation Academy applicants write an additional essay.', 30, true, 'Common App is the only way to apply. International-school applicants submit transcripts (at least three years) and a course-by-course credential evaluation instead of the STARS self-report. The admissions pages do not mention recommendation letters or an interview.', '2c84cc4e-dc19-5d91-a72e-9ac787aa7dff');
