insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('cda0864c-0713-5272-a8ef-41aead30c138', 'required_nonnative', 'Required for non-US citizens/non-permanent residents. Waived if you will have lived in a country where English is the primary language, or attended a school with English as the primary language of instruction, for at least the last four years (including the current year) before enrolling. English-course grades and SAT/ACT do not qualify.', 'ae6fc595-51ff-5e60-b0cd-0508e0690c89');
