insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('000e7378-5194-59a3-9fce-dc985403e2f0', '2026-27', 'optional', 'ACT/SAT scores are not required for international students; first-year applicants who have taken either test are recommended to submit official scores. SAT 1120 or ACT 22 can substitute for the 3.0 GPA requirement.', '27e23978-8f4d-5581-8ae6-d3da01a9606c');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('000e7378-5194-59a3-9fce-dc985403e2f0', '2026-27', array['common_app','own']::text[], 95, 'International first-year admission requires a 3.0 cumulative GPA OR SAT 1120 (EBRW + Math) OR ACT 22. Apply with the UNLV application or the Common App (no preference); $95 nonrefundable international fee. Send the high school transcript (certified translation if not in English; PDF with grading key) and proof of English proficiency; after admission upload the Confidential Financial Certification form and a bank letter for the I-20.', '27e23978-8f4d-5581-8ae6-d3da01a9606c');
insert into deadlines (id, institution_id, cycle, kind, label, due_date, notes, source_id) values
 ('6f7eda43-0cf2-58af-862c-39f82d2c077e', '000e7378-5194-59a3-9fce-dc985403e2f0', '2026-27', 'priority', 'Fall first-year priority deadline', '2026-11-15', 'To get priority for institutional grants and scholarships an applicant must be admitted and complete the Institutional Aid Application / Alternative Need Form by this date; applications open Oct. 1. The page prints no year; taken as the current cycle.', '27e23978-8f4d-5581-8ae6-d3da01a9606c'),
 ('d3c6a14f-04a9-5736-a2ac-f6bfe4390221', '000e7378-5194-59a3-9fce-dc985403e2f0', '2026-27', 'application', 'Fall first-year application deadline', '2027-06-01', 'Spring deadline is Dec. 1. I-20 processing starts 6 weeks before the semester for initial F-1 applicants. UNLV''s College of Engineering IEP page lists earlier dates (May 1 for fall), which were not confirmed on the admissions page.', '27e23978-8f4d-5581-8ae6-d3da01a9606c');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('000e7378-5194-59a3-9fce-dc985403e2f0', 'required_nonnative', 'Other accepted proof: SAT EBRW 480+, ACT English 18+, ELS Level 109, MET 53, CEFR B2, or ENG 113/ENG 101 with a C or better. Exempt: a degree from a U.S. institution; being from or earning a degree in a listed English-speaking nation (e.g. Canada excluding Quebec, Ireland, Nigeria, the Philippines, Singapore, South Africa, the United Kingdom); or a degree earned outside the U.S. where English was the primary language of instruction. Scores must be under two years old. English Language Center Fast Track: applicants who meet everything but English (TOEFL iBT 59-71 or new 3.0-3.5, IELTS 5.0-5.5, Duolingo 85-90, PTE 43-58) enroll full-time in the non-credit Intensive English Program; finishing Level 4 with a C or better satisfies the requirement without a new test.', 'f409e8d8-70d9-5440-9879-70732218f6eb');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, min_subscores, notes)
select '000e7378-5194-59a3-9fce-dc985403e2f0'::uuid, 'required_option', 'f409e8d8-70d9-5440-9879-70732218f6eb'::uuid, v.* from (values
 ('TOEFL_IBT', 72, '{"each_section": 17}'::jsonb, 'Legacy 0-120 scale; no band below 17.'),
 ('TOEFL_IBT_2026', 4.0, '{"each_section": 3.5}'::jsonb, 'New 1-6 scale, tests from January 2026; no band below 3.5.'),
 ('IELTS', 6.0, '{"each_section": 5.5}'::jsonb, 'IELTS Academic.'),
 ('DUOLINGO', 100, '{"each_section": 95}'::jsonb, null),
 ('PTE', 59, '{"each_section": 50}'::jsonb, 'PTE Academic.')) v;
