insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('51734219-668a-531e-a573-e38f256c6c43', '2026-27', 'optional', 'ACT, SAT, CLT and other scores are not required to be considered for admission but may be helpful in some cases. Engineering applicants (all Electrical and Computer Engineering) must still submit an English proficiency score.', '55e11546-79df-56cf-be2a-6e6bd62e5a3c');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('51734219-668a-531e-a573-e38f256c6c43', '2026-27', array['own']::text[], 50, 'International applicants apply online and pay a $50 fee (the domestic freshman fee is $25), then send official transcripts, graduation certificates (translated if needed) and English scores. Essays, portfolios and recommendations are not needed for admission (domestic freshman page). Funding for one year must be shown before the I-20 is issued.', '8738f62e-359b-555e-81c7-8f6778705aa3');
insert into deadlines (id, institution_id, cycle, kind, label, due_date, notes, source_id) values
 ('76ac0938-7dca-5617-bda5-2eb8d8969c98', '51734219-668a-531e-a573-e38f256c6c43', '2026-27', 'priority', 'Priority application, fall 2027 (international)', '2027-03-01', 'International Admissions lists March 1, 2027 priority and May 1, 2027 final for fall 2027 entry because of visa appointment delays. Domestic freshmen have a June 1 priority date.', '8738f62e-359b-555e-81c7-8f6778705aa3'),
 ('17ce873f-c119-5208-b5db-6d73a009061a', '51734219-668a-531e-a573-e38f256c6c43', '2026-27', 'application', 'Final application deadline, fall 2027 (international)', '2027-05-01', null, '8738f62e-359b-555e-81c7-8f6778705aa3'),
 ('60b588ab-e827-5188-9892-669a163d6c64', '51734219-668a-531e-a573-e38f256c6c43', '2026-27', 'other', 'Required documents deadline, fall 2027 (international)', '2027-06-01', null, '8738f62e-359b-555e-81c7-8f6778705aa3'),
 ('03139efd-58a3-59f3-b2e4-7128b358ef5b', '51734219-668a-531e-a573-e38f256c6c43', '2026-27', 'scholarship', 'Priority scholarship consideration, fall admission', '2027-03-15', 'Transcripts and English scores should be received by this date for best consideration; later applicants are considered as funds allow. Spring admission priority is May 1.', 'b15d384c-b857-57c8-bf9c-d392fc3dfe0b');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('51734219-668a-531e-a573-e38f256c6c43', 'required_nonnative', 'Test not required with four years of U.S. high school at a 2.5+ GPA, ACT English 19+, SAT EBRW 500+, or two semesters of freshman English composition (C or better) at a regionally accredited U.S. college; Electrical and Computer Engineering applicants must still submit a proficiency score. Other accepted: TOEFL Essentials B2, LanguageCert 68 (no skill below 60), Oxford Test of English 125, PTE Express 76. Conditional admission: students who meet academic requirements but not English can start in UNM''s Center for English Language and American Culture (CELAC), pay a $50 CELAC fee, and transfer to degree study on CELAC''s recommendation (TOEFL PBT 520 also accepted on that page).', '7929622b-0c3a-5d0f-a5bf-7ba44bb7cc5e');
insert into english_requirements (institution_id, source_id, test_key, status, min_total, notes)
select '51734219-668a-531e-a573-e38f256c6c43'::uuid, '7929622b-0c3a-5d0f-a5bf-7ba44bb7cc5e'::uuid, v.* from (values
 ('TOEFL_IBT', 'required_option', 68, null),
 ('TOEFL_IBT_2026', 'required_option', 4.0, 'Page prints ''68 (4.0)''.'),
 ('IELTS', 'required_option', 6.0, null),
 ('DUOLINGO', 'required_option', 95, null),
 ('PTE', 'required_option', 47, null),
 ('CAMBRIDGE', 'accepted', null, 'Cambridge C1 Advanced (CAE) at level C1 or C2 Proficiency (CPE); the page gives a CEFR level, not a numeric score.')) v;
