insert into admission_stats (institution_id, cds_year, applicants, pct_submit_sat, pct_submit_act, notes, source_id, source_note) values
 ('67a7428c-9258-589e-93cb-d9752e9ebd32', '2024-2025', 24623, 70.0, 12.0, 'Baseline from IPEDS College Navigator (fall 2024 entering class); no Common Data Set could be found on uta.edu. Navigator gives 24,623 applicants and 80% admitted (79% of men, 81% of women) but no admitted or enrolled counts, so those are left null; 26% of admitted students enrolled. SAT scores were submitted by 3,638 enrolled first-timers (70%) and ACT by 599 (12%). SAT total, GPA, residency and international splits come from the CDS and are not added.', '94f68322-0dcb-5f70-9059-a3102462be12', 'admissions_site');
insert into test_score_percentiles (institution_id, cds_year, source_id, test, p25, p50, p75)
select '67a7428c-9258-589e-93cb-d9752e9ebd32'::uuid, '2024-2025', '94f68322-0dcb-5f70-9059-a3102462be12'::uuid, v.* from (values
 ('SAT_ERW', 510, 560, 620),
 ('SAT_MATH', 500, 560, 620),
