insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('159ac21f-c009-5d9e-9d09-b6ff8f6e10ad', '2026-27', 'required', 'At least one official SAT or ACT score must be sent by the testing agency (self-report in MyStatus allowed, official must arrive by the deadline). Classic Learning Test (CLT) also satisfies the requirement. SAT Essay/ACT Writing not required. Matches CDS C8A (required to be considered).', '0d7954f6-7bd8-5ff4-9d34-b392e841450a');
insert into application_requirements (institution_id, cycle, platforms, supplemental_essays, app_fee_usd, notes, source_id) values
 ('159ac21f-c009-5d9e-9d09-b6ff8f6e10ad', '2026-27', array['common_app','own']::text[], 'At least one essay plus required short-answer prompts', 75, 'Platforms: Common App or ApplyTexas. Fee is $75 domestic; international applicants pay $90 and fee waivers are not available to international students. Up to two recommendation letters may be submitted (not mandatory per the page).', 'fcee4e46-8eb7-52ad-a7cf-92a53c0682be');
