insert into admission_stats (institution_id, cds_year, applicants, admits, enrolled, pct_submit_sat, pct_submit_act, notes, source_id, source_note) values
 ('43870941-5645-5abb-a696-bdbbca1f7b7a', '2023-2024', 13542, 11486, 5634, 28, 26, 'IPEDS ADM2023 (fall 2023 first-time students): 13,542 applicants, 11,486 admitted, 5,634 enrolled. College Navigator fall 2024: 18,377 applicants, 94% admitted. IPEDS reports no nonresident-alien applicant counts for UTRGV, so international admit figures are null; nonresidents are about 2% of undergraduates (fall 2024, rounded). Undergraduate enrollment 28,674 and student-faculty ratio 20:1 are fall 2024 College Navigator figures. No readable Common Data Set was found for this college, so this is the IPEDS baseline; GPA, residency and class-rank details are not included.', '577f4f4c-ad4d-587a-9381-a31a56f6eb70', 'admissions_site');
