insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('cb2a3dbe-19e1-5294-93fc-de79851e7042', '2026-27', 'optional', 'UWM is test-optional: ''UWM will consider applicants for admission with or without one of these standardized test scores.'' International bachelor''s applicants may submit SAT/ACT but they are not required; scores are used for math/English placement and can improve scholarship eligibility.', 'e0e1db6c-4429-500e-8950-44b4eae33fb0');
insert into application_requirements (institution_id, cycle, platforms, supplemental_essays, app_fee_usd, notes, source_id) values
 ('cb2a3dbe-19e1-5294-93fc-de79851e7042', '2026-27', array['common_app','own']::text[], 'Essay (250-650 words) is optional but recommended.', 0, 'No application fee for undergraduate (bachelor''s) programs; admitted international students pay a $200 International Student Processing Fee. Apply with the UW System Application or the Common App. Recommendation letters are optional. No minimum GPA is published; classroom performance is the main factor. Admission is conditional on the final transcript.', 'e0e1db6c-4429-500e-8950-44b4eae33fb0');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('aecf9c03-ba8d-5cf0-966b-e80f01d436ea', 'cb2a3dbe-19e1-5294-93fc-de79851e7042', '2026-27', 'priority', null, 'Priority date (fall 2027 entry)', '2026-11-01', 'CDS 2025-26 (C14) prints Nov. 1 as the priority date without a year; treated as the 2026-27 cycle.', 'e0e1db6c-4429-500e-8950-44b4eae33fb0'),
 ('d19d2f63-cd4d-5d1f-beb9-10b451edde52', 'cb2a3dbe-19e1-5294-93fc-de79851e7042', '2026-27', 'scholarship', null, 'International admits: be admitted by this date for full scholarship consideration (fall)', '2027-05-01', 'International merit awards are made monthly until funds run out; no separate application.', 'f4e3515d-4b8b-58ce-9729-fe82a8f99b1f'),
 ('1ef320a3-d4ea-56ca-a77d-b6670a99bca6', 'cb2a3dbe-19e1-5294-93fc-de79851e7042', '2026-27', 'application', 'ROLLING', 'International application deadline, fall 2027 (applicants outside the U.S.)', '2027-06-01', 'Applicants already inside the U.S.: Aug. 1. The page prints deadlines without a year; treated as fall 2027. CDS C14 lists Aug. 1 as the general closing date with rolling admission from Aug. 1.', 'f4e3515d-4b8b-58ce-9729-fe82a8f99b1f');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('cb2a3dbe-19e1-5294-93fc-de79851e7042', 'required_nonnative', 'Proof can be a qualifying test score, at least 18 months of full-time English-medium university study, or completion of the last two years of English-medium secondary school. Test scores must be no more than 2 years old. TOEFL Home Edition is not accepted. All new students take an English placement test on arrival.', 'c5ae8898-8d78-543a-a9db-ccaed2843648');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
select 'cb2a3dbe-19e1-5294-93fc-de79851e7042'::uuid, 'required_option', 'c5ae8898-8d78-543a-a9db-ccaed2843648'::uuid, v.* from (values
 ('TOEFL_IBT', 74, 'Full admission, tests before 2026-01-21. Conditional ''Foundation'' admission: 69-73 (up to two semesters of English for Academic Purposes alongside degree courses). TOEFL Home Edition not accepted.'),
 ('TOEFL_IBT_2026', 4.0, 'Full admission, tests on/after 2026-01-21 (page does not name the 1-6 scale). Foundation admission: 3.5.'),
 ('IELTS', 6.0, 'Foundation admission: 5.5.'),
 ('DUOLINGO', 105, 'Foundation admission: 95-100. Score report can be uploaded to the application portal.'),
 ('PTE', 46, 'Listed as PTEA. Foundation admission: 36-45.')) v;
insert into score_codes (institution_id, test_key, code, notes, source_id) values
 ('cb2a3dbe-19e1-5294-93fc-de79851e7042', 'toefl', '1473', 'UWM TOEFL (ETS) code; scores must be sent electronically by ETS.', 'c5ae8898-8d78-543a-a9db-ccaed2843648');
insert into cost_aid (institution_id, year, tuition_intl_usd, required_fees_usd, other_usd, total_coa_usd, intl_aid_policy, intl_need_aid_awarded, intl_avg_award_usd, meets_full_need, merit_scholarships, notes, source_id) values
 ('cb2a3dbe-19e1-5294-93fc-de79851e7042', '2026-2027', 22247, 2158, 15000, 41663, 'merit_only', 152, 4117, false, true, 'UWM international cost page (2026-27, two semesters): nonresident tuition $22,247 plus segregated and international student fees $2,158; page estimate of $41,663 includes $15,000 living expenses (12 months) and $2,258 international health insurance (12 months). CDS H6 (2024-25 aid): 152 degree-seeking nonresident undergraduates received institutional aid, average $4,117. A $200 International Student Processing Fee is due after admission.; Newly admitted international degree-seeking undergraduates are automatically considered for an academic-merit scholarship of up to $6,000 per academic year ($3,000 per semester), renewable for up to four years; no separate application. CDS H6 also ticks institutional need-based and non-need-based aid for nonresidents, but no international need-based program is described on the CIE page.', '25e8d501-d3c5-5afb-81bf-fd105b053b89');
