insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('1ce62010-20c1-5878-a296-f8ae611cde9b', '2026-27', 'optional', 'Test-optional through the 2026-27 admission campaign (class of 2031). Official or self-reported scores accepted; SAT/ACT superscored across dates. Scores reported by Nov 10 (ED I/EA) or Jan 31 (ED II/RD) are considered. Homeschooled applicants (more than one full year) must submit scores.', '7f6c1e32-5d1b-5241-a304-c0e0b0a3aaa1');
insert into application_requirements (institution_id, cycle, platforms, supplemental_essays, teacher_recs, counselor_rec, interview, app_fee_usd, css_profile_required, notes, source_id) values
 ('1ce62010-20c1-5878-a296-f8ae611cde9b', '2026-27', array['common_app','coalition']::text[], 'Villanova writing supplements (Common App Member School section or Coalition Part II).', 1, false, 'not_offered', 80, true, 'One teacher recommendation required; a counselor letter is optional but the counselor Secondary School Report and official transcript are required. Senior-year grades required for ED II, RD and deferred applicants. Villanova does not conduct interviews or consider demonstrated interest. Need-based aid needs both FAFSA and CSS Profile (code 2959). International applicants submit a Certification of Finances and bank statement.', '7f6c1e32-5d1b-5241-a304-c0e0b0a3aaa1');
