insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('11898a70-3021-526f-9eb2-79cf6b3bbdc5', '2026-27', 'optional', 'SAT/ACT scores are optional and "only required if you indicate in your application that you want them considered"; self-reported scores accepted, multiple sittings are superscored. Students who wanted scores considered must send official scores in the summer before arrival.', 'eb118d49-4b1e-5514-ac54-535d4003c442');
insert into application_requirements (institution_id, cycle, platforms, supplemental_essays, interview, app_fee_usd, notes, source_id) values
 ('11898a70-3021-526f-9eb2-79cf6b3bbdc5', '2026-27', array['common_app','coalition','own']::text[], 0, 'optional_informational', 85, 'Required: $85 fee, application, official high school transcript, Secondary School Report, and one letter of recommendation from either a counselor/advisor or a teacher; Early Decision Agreement for ED I/II; TOEFL, IELTS or Duolingo for international applicants. Optional: counselor recommendation, supplemental questions, video or virtual interview, SAT/ACT, mid-year report. Fee waivers are available on request. Coalition application is listed for domestic first-year students only (international first-years use the Common App or the Wake Forest print application).', 'eb118d49-4b1e-5514-ac54-535d4003c442');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notification_date, notes, source_id) values
 ('c873f89c-c148-54b7-b552-877afff08d99', '11898a70-3021-526f-9eb2-79cf6b3bbdc5', '2026-27', 'application', 'ED', 'Early Decision I', '2026-11-15', null, 'Binding; decisions on a rolling basis (no fixed date published).', 'eb118d49-4b1e-5514-ac54-535d4003c442'),
 ('36c86292-7411-5c45-9117-18fc1aaa7f43', '11898a70-3021-526f-9eb2-79cf6b3bbdc5', '2026-27', 'application', 'EA', 'Early Action (first-generation college students only)', '2026-11-15', '2027-01-15', 'Non-binding; admitted students have until May 1 to decide. Open to first-generation applicants only (parents have not graduated from a four-year college).', 'eb118d49-4b1e-5514-ac54-535d4003c442'),
 ('4f3f7d74-c5d1-5ca6-b282-e2371b2244dc', '11898a70-3021-526f-9eb2-79cf6b3bbdc5', '2026-27', 'application', 'ED2', 'Early Decision II', '2027-01-01', '2027-02-15', 'Binding.', 'eb118d49-4b1e-5514-ac54-535d4003c442'),
 ('1704f082-ac7f-5ec6-be13-4c840cba8b0e', '11898a70-3021-526f-9eb2-79cf6b3bbdc5', '2026-27', 'application', 'RD', 'Regular Decision', '2027-01-01', null, 'Non-binding; the page says applicants hear back "around April 1" (no fixed date).', 'eb118d49-4b1e-5514-ac54-535d4003c442');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('11898a70-3021-526f-9eb2-79cf6b3bbdc5', 'required_nonnative', 'Required for international applicants whose first language is not English and/or who attend a school where English is not the medium of instruction; waived for schools where English is the main language of instruction (3 years minimum). Self-reported scores accepted; no superscoring. TOEFL iBT scores from before the January 1, 2026 format change are still accepted.', '9501101a-d67d-5ca6-9552-80e930ffb893');
insert into english_requirements (institution_id, status, notes, source_id, test_key)
