insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('29b755b7-4fc7-561e-b2a5-e257d04e010d', 'required_nonnative', 'International students whose second language is English must submit TOEFL, IELTS or Duolingo. Students with 3+ years in an English-medium program may be exempted if academically strong (mostly-online schools typically do not qualify); other cases reviewed individually (admissions@wustl.edu). From fall 2027, SAT/ACT scores no longer substitute. Last tests accepted: December 2026 (October for EA/ED I). Undocumented/DACA students are not required to submit.', '8d392d23-0c2e-5748-8c8e-5a02ebe17a75');
