 ('act', null, 'WMU''s international pages do not print an ACT code; look it up at act.org.', '0da89cb9-2457-581c-b852-a87f5695468d'::uuid),
 ('toefl', '1902', 'WMU institutional code for TOEFL and other ETS exams.', '0da89cb9-2457-581c-b852-a87f5695468d'::uuid),
 ('ielts', null, 'No code listed: reports can be emailed by the testing agency, mailed to International Student and Scholar Services, or hand-delivered.', 'ddfd588c-c1b6-5c0d-b6e4-10b3217ff428'::uuid),
 ('duolingo', null, 'No code listed: reports can be emailed by the testing agency, mailed to International Student and Scholar Services, or hand-delivered.', 'ddfd588c-c1b6-5c0d-b6e4-10b3217ff428'::uuid),
