insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('1fc27a15-e777-5e46-b48e-fbdfee783e71', '2026-27', 'optional', 'Option 1 admits international freshmen on high school grades and the SAT or ACT is not required. Option 2 admits on test results alone (SAT 1060 combined EBRW+Math with 490+ on each section, or ACT composite 21 with 18+ on every section) and is meant for students who want admission before finishing high school or attended an unrecognized school. SAT/ACT are not used for the Global Select scholarship.', 'c9a2985f-8ebe-5d69-b648-d51c24b29f9b');
insert into application_requirements (institution_id, cycle, platforms, app_fee_usd, notes, source_id) values
 ('1fc27a15-e777-5e46-b48e-fbdfee783e71', '2026-27', array['own']::text[], 75, 'Application fee depends on processing speed: Basic $75 (4-5 weeks), Standard $150 (2-3 weeks), Premium $250 (3 business days); fees are non-refundable. Required: certification of financial support, bank statement, official transcripts from all schools (front and back), passport name page, and TOEFL/IELTS/SAT/ACT results are optional at application (see English notes). The grade needed for admission under Option 1 depends on the country; the specific minimum was not on the pages read. Select ''International Undergraduate or Intensive English'' when starting the application.', 'be4b9c4b-8348-5238-b6a5-f50d6f7a8699');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('4042dff7-9764-5947-a7e6-12c9f19e2d79', '1fc27a15-e777-5e46-b48e-fbdfee783e71', '2026-27', 'application', 'ROLLING', 'Fall 2027 international application deadline, Basic service ($75, 4-5 weeks)', '2027-04-15', 'Processing time starts when ALL documents are received. Classes begin mid-August 2027.', 'f9701d3c-ab31-5f18-80d1-897cd3c21be2'),
 ('aa36ccfa-a029-5df8-a7d6-d277da09dc57', '1fc27a15-e777-5e46-b48e-fbdfee783e71', '2026-27', 'application', 'ROLLING', 'Fall 2027 international application deadline, Standard service ($150, 2-3 weeks)', '2027-06-01', null, 'f9701d3c-ab31-5f18-80d1-897cd3c21be2'),
 ('eef23c3d-f4b8-52d0-a2ac-2fe3f5606802', '1fc27a15-e777-5e46-b48e-fbdfee783e71', '2026-27', 'application', 'ROLLING', 'Fall 2027 international application deadline, Premium service ($250, 3 business days)', '2027-07-01', 'Spring 2027 entry: Sep. 15 / Nov. 1 / Dec. 1, 2026 for Basic / Standard / Premium.', 'f9701d3c-ab31-5f18-80d1-897cd3c21be2');
insert into english_policies (institution_id, policy, waiver_notes, source_id) values
 ('1fc27a15-e777-5e46-b48e-fbdfee783e71', 'recommended', 'A TOEFL or IELTS score is not required to apply; it can be sent later, or WSU tests English after arrival (WSU English Proficiency Exam, $75). Students who do not meet the English requirement get conditional admission and enroll in the Intensive English Language Center; the I-20 then lists Intensive English with a note of the academic admission. Half-time academic study alongside Intensive English is allowed with lower scores (TOEFL 61-71 / 3.5 new scale, IELTS 5.5, Duolingo 95-104, PTE 40-48). Also accepted: SAT EBRW 410, ACT English 20, Cambridge A/AS English grade C, 24 U.S. college credits, four years of U.S. high school English with C+. Tests must be less than two years old; IELTS General Training and One Skill Retake are not accepted.', '2eb09e2d-843d-5826-accc-e2178a16affc');
insert into english_requirements (institution_id, status, source_id, test_key, min_total, notes)
