insert into test_policies (institution_id, cycle, policy, notes, source_id) values
 ('0484af38-0265-5b9f-aea4-0095a7ef5c5e', '2026-27', 'optional', 'Test-optional (applicants choose whether scores are considered; no-harm practice). SAT is superscored; ACT best composite is used; science section not required. Self-reporting allowed; official scores only if you enroll. Scores are not used for merit scholarships. Last published middle 50% (fall 2021 entrants who submitted): SAT 1340-1480, ACT 30-34.', '408920a7-8fca-505b-99c5-4d1b93d11b1f');
insert into application_requirements (institution_id, cycle, platforms, teacher_recs, counselor_rec, app_fee_usd, css_profile_required, notes, source_id) values
 ('0484af38-0265-5b9f-aea4-0095a7ef5c5e', '2026-27', array['common_app']::text[], 1, true, 70, true, 'One teacher and one counselor recommendation, official transcripts (first marking period grades or mid-year report highly recommended). Early Decision applicants submit the ED Agreement form. Page says all first-year candidates use the Common Application. International students applying for need-based aid submit only the CSS Profile (no FAFSA); domestic need-based applicants need both.', 'ca242580-b055-582a-bb37-b71e899a6504');
insert into deadlines (id, institution_id, cycle, kind, plan_key, label, due_date, notes, source_id) values
 ('8d49ed87-60a5-50de-bf5f-8f479bf00379', '0484af38-0265-5b9f-aea4-0095a7ef5c5e', '2026-27', 'application', 'ED', 'Early Decision I', '2026-11-01', 'Binding. Notification by mid December (no exact date). Admitted ED students get a minimum merit scholarship of $25,000 per year. Need-based aid documents also due Nov 1.', 'a75703ea-0f68-55cb-ba38-6c1feea65d6e'),
 ('2868846e-bf86-500b-b3bf-d609698886b1', '0484af38-0265-5b9f-aea4-0095a7ef5c5e', '2026-27', 'application', 'ED2', 'Early Decision II', '2027-01-05', 'Binding. Notification by mid February (no exact date).', 'a75703ea-0f68-55cb-ba38-6c1feea65d6e'),
 ('2b61f0c2-0fda-5e9b-a4ab-127d35335b83', '0484af38-0265-5b9f-aea4-0095a7ef5c5e', '2026-27', 'application', 'EA', 'Early Action I', '2026-11-01', 'Non-binding. Decision by mid December; reply by May 1.', 'a75703ea-0f68-55cb-ba38-6c1feea65d6e'),
 ('1756bf8e-c3ae-5674-8ae2-e167016d16d4', '0484af38-0265-5b9f-aea4-0095a7ef5c5e', '2026-27', 'application', 'EA', 'Early Action II', '2027-01-05', 'Non-binding. Decision by mid February.', 'a75703ea-0f68-55cb-ba38-6c1feea65d6e'),
 ('a3514ded-2a58-5a32-b152-c744aaf1f2e8', '0484af38-0265-5b9f-aea4-0095a7ef5c5e', '2026-27', 'application', 'RD', 'Regular Decision', '2027-02-01', 'Decision by mid March (ED I deferrals are notified before March 15).', 'a75703ea-0f68-55cb-ba38-6c1feea65d6e');
